    let out=r.items.map(it=>'<div style="padding:8px;border:1px solid #ddd;border-radius:8px;margin-top:6px">شناسه چت: <b dir="ltr" style="user-select:all">'+it.chatId+'</b>'+(it.name?' — نام: '+it.name:'')+(it.text?' — متن: «'+it.text.slice(0,40)+'»':'')+'</div>').join('');
