  function clsUpdateParticipants(list){
    document.getElementById('cls-online-count').textContent=list.filter(p=>p.role==='student').length;
    document.getElementById('cls-participants').innerHTML=list.map(p=>(p.role==='teacher'?'👨‍🏫 ':'👤 ')+esc(p.name)).join('<br>')||'<span class="muted">کسی متصل نیست</span>';
    clsPruneStudentMedia(list);
  }

  // ===== دوربین/صدای زنده‌ی دانش‌آموزان (نمایش برای معلم) =====
  const studentCamTiles={}; // id -> {tile, img, off, nameEl}
  const studentAudioQ={}; // id -> {queue:[], playing:false}
  function clsStudentCamGridEmptyCheck(){
    const grid=document.getElementById('t-student-cams');
    if(!Object.keys(studentCamTiles).length){
      grid.innerHTML='<span class="muted" style="font-size:12px">دوربینی روشن نیست</span>';
    }
  }
  function ensureStudentCamTile(id,name){
    const grid=document.getElementById('t-student-cams');
    if(studentCamTiles[id]){
      if(name)studentCamTiles[id].nameEl.textContent=name;
      return studentCamTiles[id];
    }
    const emptyMsg=grid.querySelector('.muted');
    if(emptyMsg)emptyMsg.remove();
    const tile=document.createElement('div');
    tile.className='cls-cam-tile';
    tile.innerHTML='<img class="hidden"><div class="cls-cam-tile-off">🎥 خاموش</div><div class="cls-cam-tile-name"></div>';
    grid.appendChild(tile);
    const obj={tile, img:tile.querySelector('img'), off:tile.querySelector('.cls-cam-tile-off'), nameEl:tile.querySelector('.cls-cam-tile-name')};
    obj.nameEl.textContent=name||'دانش‌آموز';
    studentCamTiles[id]=obj;
    return obj;
  }
  function studentGetAudioCtx(){ if(!window.__studentAudioCtx) window.__studentAudioCtx=new (window.AudioContext||window.webkitAudioContext)(); return window.__studentAudioCtx; }
  function playStudentAudio(id, b64, mime, meta){
    let st=studentAudioQ[id];
    if(!st) st=studentAudioQ[id]={nextTime:0, chain:Promise.resolve()};
    st.chain=st.chain.then(async()=>{
      try{
        const ctx=studentGetAudioCtx();
        const binary=atob(b64);
        const bytes=new Uint8Array(binary.length);
        for(let i=0;i<binary.length;i++) bytes[i]=binary.charCodeAt(i);
        const audioBuffer=await ctx.decodeAudioData(bytes.buffer);
        const now=ctx.currentTime;
        const _ld=(meta&&+meta.lead>0&&+meta.lead<0.6)?+meta.lead:0;
        let _body=(meta&&+meta.len>0&&+meta.len<=2)?+meta.len:0;
        if(!_body||_ld+_body>audioBuffer.duration+0.03) _body=Math.max(0.05,audioBuffer.duration-_ld);   // اگر اطلاعات همپوشانی نبود، کل تکه پخش می‌شود
        const _lag=st.nextTime-now;
        if(!st.primed||_lag<0){ st.nextTime=now+(st.primed?0.2:0.3); st.primed=true; }   // صف خالی شد یا شروع: کمی بافر بساز
        else if(_lag>1.0){ st.nextTime=now+0.3; }   // تأخیر انباشته شد: به زمان حال برگرد
        const src=ctx.createBufferSource();
        src.buffer=audioBuffer;
        src.connect(ctx.destination);
        src.start(st.nextTime, _ld, _body);
        st.nextTime += _body;
      }catch(e){}
    });
  }
  function clsPruneStudentMedia(list){
    const activeIds=new Set(list.filter(p=>p.role==='student').map(p=>p.id));
    Object.keys(studentCamTiles).forEach(id=>{
      if(!activeIds.has(id)){ studentCamTiles[id].tile.remove(); delete studentCamTiles[id]; }
    });
    Object.keys(studentAudioQ).forEach(id=>{ if(!activeIds.has(id)) delete studentAudioQ[id]; });
    clsStudentCamGridEmptyCheck();
  }

  document.getElementById('btn-cls-start').onclick=async()=>{
    // باز کردن قفل پخش خودکار صدای دانش‌آموزان در همین لحظه (چون این کلیک، تعامل مستقیم کاربر است)
    try{ const unlockA=new Audio('data:audio/wav;base64,UklGRiQAAABXQVZFZm10IBAAAAABAAEAQB8AAEAfAAABAAgAZGF0YQAAAAA='); unlockA.play().catch(()=>{}); }catch(e){}
    const startBtn=document.getElementById('btn-cls-start');
    rmBegin('cls');
    startBtn.disabled=true;
    document.getElementById('t-cls-status').textContent='در حال بررسی...';
    try{
      const chk=await fetch('/api/classroom/ws?check=1&role=teacher');
      const chkData=await chk.json().catch(()=>({ok:false,error:'پاسخ نامعتبر از سرور'}));
      if(!chkData.ok){
        document.getElementById('t-cls-status').textContent='خطا: '+chkData.error;
        startBtn.disabled=false;
        rmAutoFail('cls','btn-cls-start');
        toast(chkData.error);
        return;
      }
    }catch(e){
      document.getElementById('t-cls-status').textContent='خطا در ارتباط با سرور';
      startBtn.disabled=false;
      rmAutoFail('cls','btn-cls-start');
      return;
    }
    startBtn.disabled=false;
    const proto=location.protocol==='https:'?'wss:':'ws:';
    clsWs=new WebSocket(proto+'//'+location.host+'/api/classroom/ws?role=teacher&name='+encodeURIComponent('معلم'));
    const myWs=clsWs;
    clsWs.onopen=()=>{RM.cls.ever=true;RM.cls.retry=0;RM.cls.inAuto=false;rmStartHb('cls',function(){return clsWs;});
      document.getElementById('tdot').classList.add('on');
      document.getElementById('t-cls-status').textContent='کلاس آنلاین فعال است ✅';
      document.getElementById('btn-cls-start').classList.add('hidden');
      document.getElementById('btn-cls-stop').classList.remove('hidden');
      document.getElementById('btn-mic-toggle').classList.remove('hidden');
      document.getElementById('btn-cam-toggle').classList.remove('hidden');
      toast('کلاس آنلاین شروع شد');
    };
    clsWs.onclose=()=>{
      rmStopHb('cls');
      if(rmReconnect('cls',myWs===clsWs,'tdot','t-cls-status','btn-cls-start')) return;
      document.getElementById('tdot').classList.remove('on');
      document.getElementById('t-cls-status').textContent='کلاس آنلاین شروع نشده';
      document.getElementById('btn-cls-start').classList.remove('hidden');
      document.getElementById('btn-cls-stop').classList.add('hidden');
      document.getElementById('btn-mic-toggle').classList.add('hidden');
      document.getElementById('btn-cam-toggle').classList.add('hidden');
    };
    clsWs.onmessage=(evt)=>{
      rmTouch('cls');
      let m;try{m=JSON.parse(evt.data);}catch(e){return;}
      if(m.type==='pong') return;
      if(m.type==='init'){
        if(m.boardBg){clsSetBoardBgAndReplay(m.boardBg,m.strokes||[]);}
        else{tCtx.clearRect(0,0,tBoard.width,tBoard.height);clsBoardBgImg=null;(m.strokes||[]).forEach(clsDrawLocal);}
        (m.chat||[]).forEach(clsAddChat);clsUpdateParticipants(m.participants||[]);
      }
      else if(m.type==='chat'){clsAddChat(m.entry);}
      else if(m.type==='file'){clsAddFile(m);}
      else if(m.type==='board-bg'){clsSetBoardBg(m.data);}
      else if(m.type==='error'){toast(m.message||'خطا');}
      else if(m.type==='presence'){clsUpdateParticipants(m.participants||[]);if(m.event==='join'&&m.role==='student')toast((m.count>1?(m.name+' و '+(m.count-1)+' نفر دیگر'):m.name)+' وارد کلاس شد');}
      else if(m.type==='raise-hand'){toast('✋ '+m.name+' دستش را بلند کرد');}
      else if(m.type==='video-frame' && m.role==='student'){
        const t=ensureStudentCamTile(m.id, m.from);
        __vid.show(t.img,m.data,function(){__vid.ack(clsWs,m.id||'s');});
        t.img.classList.remove('hidden');
        t.off.classList.add('hidden');
      }
      else if(m.type==='video-stop' && m.role==='student'){
        const t=studentCamTiles[m.id];
        if(t){ t.img.classList.add('hidden'); __vid.reset(t.img);t.img.src=''; t.off.classList.remove('hidden'); }
      }
      else if(m.type==='audio' && m.role==='student'){
        playStudentAudio(m.id, m.data, m.mime, m);
      }
    };
  };
  document.getElementById('btn-cls-stop').onclick=()=>{
    RM.cls.stopping=true;
    if(clsRecorder&&clsRecorder.state!=='inactive')clsRecorder.stop();
    if(clsMicStream)clsMicStream.getTracks().forEach(t=>t.stop());
    clsMicStream=null;
    document.getElementById('btn-mic-toggle').textContent='🎙️ روشن کردن میکروفون';
    if(clsCamStream){clsCamStream.getTracks().forEach(t=>t.stop());clsCamStream=null;}
    if(clsCamInterval){clearInterval(clsCamInterval);clsCamInterval=null;}
    document.getElementById('t-cam-preview').classList.add('hidden');
    document.getElementById('t-cam-preview').srcObject=null;
    document.getElementById('btn-cam-toggle').textContent='📷 روشن کردن تصویر';
    document.getElementById('btn-cam-flip').classList.add('hidden');
    clsCamFacing='user';
    clsAudioFromCam=false;
    if(clsWs)clsWs.close();
    clearActiveCameraFeature('classroom');
  };

  document.getElementById('btn-cls-options-toggle').onclick=function(){
    document.getElementById('cls-options-drawer').classList.toggle('hidden');
  };

  function clsStartMicRecorder(stream){
    if(clsAudioActive) return; // جلوگیری از راه‌اندازی دوباره و همپوشانی صدا (علت اصلی تکرار صدا)
    clsMicStream=stream;
    clsAudioActive=true;
    clsAudioGen++;
    const myGen=clsAudioGen;
    const preferredMimes=['audio/webm;codecs=opus','audio/webm','audio/mp4'];
    const mime=preferredMimes.find(m=>window.MediaRecorder && MediaRecorder.isTypeSupported(m)) || '';
    const CLIP_S=0.35, LEAD_S=0.10, TAIL_S=0.04, T0_MS=performance.now();
      function recordOneChunk(k){
        k=k||0;
      if(myGen!==clsAudioGen || !clsAudioActive || !clsMicStream) return;
      let chunks=[];
      let rec;
      try{ rec=new MediaRecorder(clsMicStream, mime?{mimeType:mime}:undefined); }
      catch(e){ clsAudioActive=false; toast('امکان ضبط صدا در این مرورگر نیست'); return; }
      rec.ondataavailable=(e)=>{ if(e.data && e.data.size>0) chunks.push(e.data); };
      rec.onstop=async()=>{
        if(myGen!==clsAudioGen) return;
        if(chunks.length){
          const blob=new Blob(chunks, {type: mime||'audio/webm'});
          const buf=await blob.arrayBuffer();
          let binary='';const bytes=new Uint8Array(buf);
          for(let i=0;i<bytes.length;i++)binary+=String.fromCharCode(bytes[i]);
          clsSend({type:'audio', data: btoa(binary), mime: mime||'audio/webm', lead: rec._lead||0, len: CLIP_S});
        }
      };
      rec.start();
      clsRecorder=rec;
      rec._lead=(k===0)?0:LEAD_S;
      // ضبط هر تکه LEAD_S ثانیه زودتر از مرز شروع می‌شود و TAIL_S ثانیه دیرتر تمام می‌شود (همپوشانی)؛ گیرنده فقط بخش اصلی را پخش می‌کند
      const endAt=T0_MS+(k+1)*CLIP_S*1000;
      setTimeout(()=>{ if(rec.state==='recording') rec.stop(); }, Math.max(0,endAt+TAIL_S*1000-performance.now()));
      setTimeout(()=>{ recordOneChunk(k+1); }, Math.max(0,endAt-LEAD_S*1000-performance.now()));
    }
    recordOneChunk();
  }
  function clsStopMicRecorder(){
    clsAudioActive=false;
    clsAudioGen++; // هر حلقه‌ی در حال اجرا با چک نسل، خودش را متوقف می‌کند
    if(clsRecorder && clsRecorder.state==='recording')clsRecorder.stop();
    if(clsMicStream)clsMicStream.getTracks().forEach(t=>t.stop());
    clsMicStream=null;
    document.getElementById('btn-mic-toggle').textContent='🎙️ روشن کردن میکروفون';
  }

  document.getElementById('btn-mic-toggle').onclick=async function(){
    if(clsRecorder && clsRecorder.state==='recording'){
      clsStopMicRecorder();
      clsAudioFromCam=false;
      return;
    }
    try{
      const stream=await navigator.mediaDevices.getUserMedia({audio:true});
      clsStartMicRecorder(stream);
      clsAudioFromCam=false;
      this.textContent='🔴 خاموش کردن میکروفون';
      toast('میکروفون فعال شد');
    }catch(e){ toast('دسترسی به میکروفون داده نشد'); }
  };

  document.getElementById('btn-cam-toggle').onclick=async function(){
    const preview=document.getElementById('t-cam-preview');
    if(clsCamStream){
      clsCamStream.getVideoTracks().forEach(t=>t.stop());
      clsCamStream=null;
      if(clsCamInterval){clearInterval(clsCamInterval);clsCamInterval=null;}
      preview.classList.add('hidden');
      preview.srcObject=null;
      this.textContent='📷 روشن کردن تصویر';
      document.getElementById('btn-cam-flip').classList.add('hidden');
      clsCamFacing='user';
      clsSend({type:'video-stop'});
      if(clsAudioFromCam){ clsStopMicRecorder(); clsAudioFromCam=false; }
      clearActiveCameraFeature('classroom');
      return;
    }
    try{
      warnIfOtherCameraActive('classroom','کلاس آنلاین');
      // نکته: عمداً فقط عرض تقریبی درخواست می‌شود، نه عرض+ارتفاع با هم؛ وقتی هر دو با هم
      // درخواست شوند و با نسبت واقعی دوربین گوشی جور نباشد، خیلی از گوشی‌های اندروید به‌جای
      // برش تصویر، دور آن را با نوار سیاه پر می‌کنند و تصویر خیلی کوچک و وسط‌چین دیده می‌شود.
      clsCamStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:clsCamFacing,width:{ideal:480}}, audio:true});
      preview.srcObject=clsCamStream;
      preview.classList.remove('hidden');
      clsUpdateCamLayout();
      this.textContent='🔴 خاموش کردن تصویر';
      document.getElementById('btn-cam-flip').classList.remove('hidden');
      // اگر میکروفون از قبل روشن نبود، صدا را هم همراه تصویر روشن کن (مثل یک تماس تصویری واقعی)
      if(!(clsRecorder && clsRecorder.state==='recording') && clsCamStream.getAudioTracks().length){
        clsStartMicRecorder(new MediaStream(clsCamStream.getAudioTracks()));
        clsAudioFromCam=true;
        document.getElementById('btn-mic-toggle').textContent='🔴 خاموش کردن میکروفون';
      }
      toast('تماس تصویری (با صدا) فعال شد');
      const cap=document.createElement('canvas');
      const capCtx=cap.getContext('2d');
      const __vs=__vid.newSender();
      clsCamInterval=setInterval(function(){ if(!clsCamStream)return; __vid.tick(__vs,preview,clsWs); },50); // ارسال تطبیقی: کیفیت/اندازه/نرخ فریم خودکار با وضعیت شبکه تنظیم می‌شود
    }catch(e){ toast('دسترسی به دوربین یا میکروفون داده نشد'); }
  };

  document.getElementById('btn-cam-flip').onclick=async function(){
    if(!clsCamStream){toast('ابتدا دوربین را روشن کنید');return;}
    const preview=document.getElementById('t-cam-preview');
    const prevFacing=clsCamFacing;
    const nextFacing=clsCamFacing==='user'?'environment':'user';
    const wasAudioFromCam=clsAudioFromCam;
    if(wasAudioFromCam){ clsStopMicRecorder(); clsAudioFromCam=false; }
    // دوربین فعلی را قبل از درخواست دوربین جدید کاملاً آزاد می‌کنیم؛ خیلی از مرورگرها/دستگاه‌ها
    // اجازه نمی‌دهند دو دوربین همزمان باز باشند و همین باعث می‌شد چرخش دوربین کار نکند.
    clsCamStream.getTracks().forEach(t=>t.stop());
    clsCamStream=null;
    preview.srcObject=null;
    try{
      const newStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{exact:nextFacing},width:{ideal:480}}, audio:true});
      clsCamStream=newStream;
      clsCamFacing=nextFacing;
      preview.srcObject=clsCamStream;
      if(wasAudioFromCam && clsCamStream.getAudioTracks().length){
        clsStartMicRecorder(new MediaStream(clsCamStream.getAudioTracks()));
        clsAudioFromCam=true;
        document.getElementById('btn-mic-toggle').textContent='🔴 خاموش کردن میکروفون';
      }
      toast('دوربین عوض شد 🔄');
    }catch(e){
      toast('این دستگاه دوربین دومی ندارد یا اجازه دسترسی به آن را نمی‌دهد');
      // تلاش برای بازگرداندن دوربین قبلی تا تصویر کلاً قطع نشود
      try{
        clsCamStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:prevFacing,width:{ideal:480}}, audio:true});
        clsCamFacing=prevFacing;
        preview.srcObject=clsCamStream;
        if(wasAudioFromCam && clsCamStream.getAudioTracks().length){
          clsStartMicRecorder(new MediaStream(clsCamStream.getAudioTracks()));
          clsAudioFromCam=true;
          document.getElementById('btn-mic-toggle').textContent='🔴 خاموش کردن میکروفون';
        }
      }catch(e2){
        toast('دسترسی به دوربین قطع شد؛ لطفاً دوباره روی «روشن کردن تصویر» بزنید');
        document.getElementById('btn-cam-toggle').textContent='📷 روشن کردن تصویر';
        document.getElementById('btn-cam-flip').classList.add('hidden');
      }
    }
  };

  // ===== تماس تعاملی (اتاق کاملاً جدا از کلاس آنلاین: تخته + چت + دوربین/صدای زنده‌ی همه) =====
  let iaWs=null, iaMicStream=null, iaRecorder=null, iaDrawing=false, iaLastPoint=null, iaCurrentStroke=null, iaAudioActive=false, iaAudioGen=0;
  let iaCamStream=null, iaCamInterval=null, iaAudioFromCam=false, iaCamFacing='user';
  const iaBoard=document.getElementById('ia-board');
  const iaCtx=iaBoard.getContext('2d');
  const IA_BOARD_DEFAULT_W=900, IA_BOARD_DEFAULT_H=560;

  function iaResizeBoard(){
    const ratio=iaBoard.height/iaBoard.width;
    const containerW=iaBoard.parentElement.clientWidth;
    if(!containerW)return;
    const maxH=window.innerHeight*0.78; // بزرگ ولی همیشه در صفحه جا می‌شود (مثل نمایشگر PDF در Adobe Connect)
    let w=containerW, h=w*ratio;
    if(h>maxH){h=maxH;w=h/ratio;}
    iaBoard.style.width=w+'px';
    iaBoard.style.height=h+'px';
  }
  function iaResizeBoardTo(w,h){
    iaBoard.width=Math.round(w);
    iaBoard.height=Math.round(h);
    iaResizeBoard();
  }
  iaResizeBoard();window.addEventListener('resize',iaResizeBoard);

  function iaPointFromEvent(e){
    const rect=iaBoard.getBoundingClientRect();
    const cx=(e.touches?e.touches[0].clientX:e.clientX)-rect.left;
    const cy=(e.touches?e.touches[0].clientY:e.clientY)-rect.top;
    return [cx/rect.width, cy/rect.height];
  }
  function iaDrawLocal(stroke){
    if(!stroke)return;
    if(stroke.type==='text'){
      iaCtx.save();
      iaCtx.fillStyle=stroke.color||'#111827';
      iaCtx.font='bold '+((stroke.size||3)*7+12)+'px Vazirmatn, Tahoma, sans-serif';
      iaCtx.textBaseline='top';
      iaCtx.fillText(stroke.text||'', stroke.x*iaBoard.width, stroke.y*iaBoard.height);
      iaCtx.restore();
      return;
    }
    if(!stroke.points||stroke.points.length<2)return;
    iaCtx.save();
    iaCtx.strokeStyle=stroke.erase?'#ffffff':(stroke.color||'#111827');
    iaCtx.lineWidth=stroke.size||3;
    iaCtx.lineCap='round';iaCtx.lineJoin='round';
    iaCtx.beginPath();
    iaCtx.moveTo(stroke.points[0][0]*iaBoard.width, stroke.points[0][1]*iaBoard.height);
    for(let i=1;i<stroke.points.length;i++)iaCtx.lineTo(stroke.points[i][0]*iaBoard.width, stroke.points[i][1]*iaBoard.height);
    iaCtx.stroke();
    iaCtx.restore();
  }
  function iaSend(obj){ if(iaWs && iaWs.readyState===1) iaWs.send(JSON.stringify(obj)); }

  // ===== لایه‌ی پس‌زمینه (صفحه‌ی PDF روی تخته) =====
  let iaBoardBgImg=null;
  // نیازی به این تابع نیست: دوربین معلم اینجا همیشه یک کارت ثابت در ردیف «تماس تصویری»
  // بالای صفحه است، نه پوششی روی تخته؛ پس اندازه/جای آن به پس‌زمینه‌ی تخته بستگی ندارد.
  function iaUpdateCamLayout(){}
  function iaSetBoardBg(dataUrl,w,h){
    if(!dataUrl){
      iaBoardBgImg=null;
      iaResizeBoardTo(w||IA_BOARD_DEFAULT_W,h||IA_BOARD_DEFAULT_H);
      iaCtx.clearRect(0,0,iaBoard.width,iaBoard.height);
      iaUpdateCamLayout();
      return;
    }
    const img=new Image();
    img.onload=()=>{
      iaBoardBgImg=img;
      iaResizeBoardTo(w||img.naturalWidth,h||img.naturalHeight);
      iaCtx.clearRect(0,0,iaBoard.width,iaBoard.height);
      iaCtx.drawImage(img,0,0,iaBoard.width,iaBoard.height);
      iaUpdateCamLayout();
    };
    img.onerror=()=>{toast('خطا در بارگذاری تصویر پس‌زمینه');};
    img.src=dataUrl;
  }
  function iaSetBoardBgAndReplay(dataUrl,strokes,w,h){
    if(!dataUrl){
      iaBoardBgImg=null;
      iaResizeBoardTo(w||IA_BOARD_DEFAULT_W,h||IA_BOARD_DEFAULT_H);
      iaCtx.clearRect(0,0,iaBoard.width,iaBoard.height);
      (strokes||[]).forEach(iaDrawLocal);
      iaUpdateCamLayout();
      return;
    }
    const img=new Image();
    img.onload=()=>{
      iaBoardBgImg=img;
      iaResizeBoardTo(w||img.naturalWidth,h||img.naturalHeight);
      iaCtx.clearRect(0,0,iaBoard.width,iaBoard.height);
      iaCtx.drawImage(img,0,0,iaBoard.width,iaBoard.height);
      (strokes||[]).forEach(iaDrawLocal);
      iaUpdateCamLayout();
    };
    img.onerror=()=>{toast('خطا در بارگذاری تصویر پس‌زمینه');};
    img.src=dataUrl;
  }

  // ===== ارسال یک عکس ساده (غیر PDF) روی تخته تماس تعاملی =====
  document.getElementById('ia-img-bg-file').addEventListener('change',function(){
    const f=this.files&&this.files[0];this.value='';
    if(!f)return;
    if(f.type.indexOf('image/')!==0){toast('فقط فایل عکس مجاز است');return;}
    const reader=new FileReader();
    reader.onload=function(){
      const dataUrl=reader.result;
      const img=new Image();
      img.onload=function(){
        iaResizeBoardTo(img.naturalWidth,img.naturalHeight);
        iaSetBoardBg(dataUrl);
        iaSend({type:'board-bg',data:dataUrl,w:img.naturalWidth,h:img.naturalHeight});
        document.getElementById('ia-img-bg-name').textContent=f.name;
        document.getElementById('ia-img-bg-remove').classList.remove('hidden');
        toast('عکس روی تخته نمایش داده شد ✅');
      };
      img.onerror=function(){toast('خطا در بارگذاری عکس');};
      img.src=dataUrl;
    };
    reader.onerror=function(){toast('خطا در خواندن فایل عکس');};
    reader.readAsDataURL(f);
  });
  document.getElementById('ia-img-bg-remove').onclick=function(){
    iaResizeBoardTo(IA_BOARD_DEFAULT_W,IA_BOARD_DEFAULT_H);
    iaSetBoardBg(null);
    iaSend({type:'board-bg',data:null,w:IA_BOARD_DEFAULT_W,h:IA_BOARD_DEFAULT_H});
    document.getElementById('ia-img-bg-name').textContent='';
    this.classList.add('hidden');
    toast('عکس از روی تخته حذف شد');
  };

  // ===== نمایش PDF روی تخته =====
  let iaPdfDoc=null, iaPdfFileName='', iaPdfCurrentPage=1;
  document.getElementById('ia-pdf-file').addEventListener('change',async function(){
    const f=this.files&&this.files[0];this.value='';
    if(!f)return;
    if(f.type!=='application/pdf'){toast('فقط فایل PDF مجاز است');return;}
    try{
      const buf=await f.arrayBuffer();
      iaPdfDoc=await pdfjsLib.getDocument({data:buf}).promise;
      iaPdfFileName=f.name;
      iaPdfCurrentPage=1;
      document.getElementById('ia-pdf-name').textContent=f.name;
      document.getElementById('ia-pdf-total').textContent=iaPdfDoc.numPages;
      const pn=document.getElementById('ia-pdf-pagenum');
      pn.value=1;pn.max=iaPdfDoc.numPages;
      document.getElementById('ia-pdf-nav').classList.remove('hidden');
      document.getElementById('ia-pdf-remove-file').classList.remove('hidden');
      toast('فایل PDF بارگذاری شد ✅ ('+iaPdfDoc.numPages+' صفحه)');
    }catch(e){
      toast('خطا در باز کردن فایل PDF - فایل معتبر است؟');
      iaPdfDoc=null;
    }
  });
  async function iaRenderPdfPage(pageNum){
    const page=await iaPdfDoc.getPage(pageNum);
    const baseViewport=page.getViewport({scale:1});
    async function renderAt(targetWidth,quality){
      const scale=targetWidth/baseViewport.width;
      const viewport=page.getViewport({scale});
      const canvas=document.createElement('canvas');
      canvas.width=viewport.width;canvas.height=viewport.height;
      const ctx=canvas.getContext('2d');
      ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);
      await page.render({canvasContext:ctx,viewport}).promise;
      return {dataUrl:canvas.toDataURL('image/jpeg',quality), w:canvas.width, h:canvas.height};
    }
    // ابتدا با کیفیت بالا رندر می‌کنیم؛ اگر حجم نهایی برای ارسال زنده خیلی بزرگ شد، به‌صورت خودکار کیفیت را کمی کاهش می‌دهیم
    let result=await renderAt(1900,0.9);
    if(result.dataUrl.length>3_000_000){
      result=await renderAt(1500,0.82);
    }
    if(result.dataUrl.length>3_000_000){
      result=await renderAt(1100,0.75);
    }
    return result;
  }
