  function iaUpdateParticipants(list){
    document.getElementById('ia-online-count').textContent=list.filter(p=>p.role==='student').length;
    document.getElementById('ia-participants').innerHTML=list.map(p=>(p.role==='teacher'?'👨‍🏫 ':'👤 ')+esc(p.name)).join('<br>')||'<span class="muted">کسی متصل نیست</span>';
    iaPruneStudentMedia(list);
    const onlineIds=new Set(list.filter(p=>p.role==='student').map(p=>String(p.id)));
    let changed=false;
    Object.keys(iaSpeakRequests||{}).forEach(function(id){ if(!onlineIds.has(id)){ delete iaSpeakRequests[id]; changed=true; } });
    Object.keys(iaAllowedSpeakers||{}).forEach(function(id){ if(!onlineIds.has(id)){ delete iaAllowedSpeakers[id]; changed=true; } });
    if(changed){ iaRenderSpeakRequests(); iaRenderAllowedSpeakers(); }
  }

  // ===== درخواست اجازه‌ی ورود به تماس: دانش‌آموز فقط بعد از تأیید معلم می‌تواند دوربین/میکروفون را روشن کند =====
  let iaSpeakRequests={}, iaAllowedSpeakers={}; // id -> name
  function iaRenderSpeakRequests(){
    const box=document.getElementById('ia-speak-requests');
    const ids=Object.keys(iaSpeakRequests);
    if(!ids.length){box.classList.add('hidden');box.innerHTML='';return;}
    box.classList.remove('hidden');
    box.innerHTML='<b style="display:block;margin-bottom:6px">✋ درخواست‌های ورود به تماس</b>'+ids.map(function(id){
      return '<div class="row" style="align-items:center;margin-bottom:4px">'
        +'<span style="flex:1">'+esc(iaSpeakRequests[id])+'</span>'
        +'<button class="btn sm" data-ia-grant="'+esc(id)+'" style="flex:0 0 auto">✅ اجازه بده</button>'
        +'<button class="btn sm gray" data-ia-deny="'+esc(id)+'" style="flex:0 0 auto">❌ رد کن</button>'
        +'</div>';
    }).join('');
    box.querySelectorAll('[data-ia-grant]').forEach(function(b){
      b.onclick=function(){
        const id=b.dataset.iaGrant;
        iaWs && iaWs.send(JSON.stringify({type:'speak-grant', id}));
        iaAllowedSpeakers[id]=iaSpeakRequests[id];
        delete iaSpeakRequests[id];
        iaRenderSpeakRequests();iaRenderAllowedSpeakers();
      };
    });
    box.querySelectorAll('[data-ia-deny]').forEach(function(b){
      b.onclick=function(){ delete iaSpeakRequests[b.dataset.iaDeny]; iaRenderSpeakRequests(); };
    });
  }
  function iaRenderAllowedSpeakers(){
    const box=document.getElementById('ia-allowed-speakers');
    const ids=Object.keys(iaAllowedSpeakers);
    if(!ids.length){box.classList.add('hidden');box.innerHTML='';return;}
    box.classList.remove('hidden');
    box.innerHTML='<b style="display:block;margin-bottom:6px">🎥 اجازه‌ی ورود به تماس دارند</b>'+ids.map(function(id){
      return '<div class="row" style="align-items:center;margin-bottom:4px">'
        +'<span style="flex:1">'+esc(iaAllowedSpeakers[id])+'</span>'
        +'<button class="btn sm danger" data-ia-revoke="'+esc(id)+'" style="flex:0 0 auto">🔇 لغو اجازه</button>'
        +'</div>';
    }).join('');
    box.querySelectorAll('[data-ia-revoke]').forEach(function(b){
      b.onclick=function(){
        const id=b.dataset.iaRevoke;
        iaWs && iaWs.send(JSON.stringify({type:'speak-revoke', id}));
        delete iaAllowedSpeakers[id];
        iaRenderAllowedSpeakers();
      };
    });
  }

  // ===== دوربین/صدای زنده‌ی دانش‌آموزان (نمایش برای معلم) =====
  const iaParticipantCamTiles={}; // id -> {tile, img, off, nameEl}
  const iaParticipantAudioQ={}; // id -> {queue:[], playing:false}
  function iaStudentCamGridEmptyCheck(){
    const grid=document.getElementById('ia-student-cams');
    if(!Object.keys(iaParticipantCamTiles).length){
      grid.innerHTML='<span class="muted" style="font-size:12px">دوربینی روشن نیست</span>';
    }
  }
  function iaEnsureCamTile(id,name){
    const grid=document.getElementById('ia-student-cams');
    if(iaParticipantCamTiles[id]){
      if(name)iaParticipantCamTiles[id].nameEl.textContent=name;
      return iaParticipantCamTiles[id];
    }
    const emptyMsg=grid.querySelector('.muted');
    if(emptyMsg)emptyMsg.remove();
    const tile=document.createElement('div');
    tile.className='cls-cam-tile';
    tile.innerHTML='<img class="hidden"><div class="cls-cam-tile-off">🎥 خاموش</div><div class="cls-cam-tile-name"></div>';
    grid.appendChild(tile);
    const obj={tile, img:tile.querySelector('img'), off:tile.querySelector('.cls-cam-tile-off'), nameEl:tile.querySelector('.cls-cam-tile-name')};
    obj.nameEl.textContent=name||'دانش‌آموز';
    iaParticipantCamTiles[id]=obj;
    return obj;
  }
  function iaGetAudioCtx(){ if(!window.__iaAudioCtx) window.__iaAudioCtx=new (window.AudioContext||window.webkitAudioContext)(); return window.__iaAudioCtx; }
  function iaPlayParticipantAudio(id, b64, mime, meta){
    let st=iaParticipantAudioQ[id];
    if(!st) st=iaParticipantAudioQ[id]={nextTime:0, chain:Promise.resolve()};
    st.chain=st.chain.then(async()=>{
      try{
        const ctx=iaGetAudioCtx();
        const binary=atob(b64);
        const bytes=new Uint8Array(binary.length);
        for(let i=0;i<binary.length;i++) bytes[i]=binary.charCodeAt(i);
        const audioBuffer=await ctx.decodeAudioData(bytes.buffer);
        const now=ctx.currentTime;
        const _ld=(meta&&+meta.lead>0&&+meta.lead<0.6)?+meta.lead:0;
        let _body=(meta&&+meta.len>0&&+meta.len<=2)?+meta.len:0;
        if(!_body||_ld+_body>audioBuffer.duration+0.03) _body=Math.max(0.05,audioBuffer.duration-_ld);   // اگر اطلاعات همپوشانی نبود، کل تکه پخش می‌شود
        const _lag=st.nextTime-now;
        if(!st.primed||_lag<0){ st.nextTime=now+(st.primed?0.2:0.3); st.primed=true; }   // صف خالی شد یا شروع: کمی بافر بساز
        else if(_lag>1.0){ st.nextTime=now+0.3; }   // تأخیر انباشته شد: به زمان حال برگرد
        const src=ctx.createBufferSource();
        src.buffer=audioBuffer;
        src.connect(ctx.destination);
        src.start(st.nextTime, _ld, _body);
        st.nextTime += _body;
      }catch(e){}
    });
  }
  function iaPruneStudentMedia(list){
    const activeIds=new Set(list.filter(p=>p.role==='student').map(p=>p.id));
    Object.keys(iaParticipantCamTiles).forEach(id=>{
      if(!activeIds.has(id)){ iaParticipantCamTiles[id].tile.remove(); delete iaParticipantCamTiles[id]; }
    });
    Object.keys(iaParticipantAudioQ).forEach(id=>{ if(!activeIds.has(id)) delete iaParticipantAudioQ[id]; });
    iaStudentCamGridEmptyCheck();
  }

  document.getElementById('btn-ia-start').onclick=async()=>{
    // باز کردن قفل پخش خودکار صدای دانش‌آموزان در همین لحظه (چون این کلیک، تعامل مستقیم کاربر است)
    try{ const unlockA=new Audio('data:audio/wav;base64,UklGRiQAAABXQVZFZm10IBAAAAABAAEAQB8AAEAfAAABAAgAZGF0YQAAAAA='); unlockA.play().catch(()=>{}); }catch(e){}
    const startBtn=document.getElementById('btn-ia-start');
    rmBegin('ia');
    startBtn.disabled=true;
    document.getElementById('ia-status').textContent='در حال بررسی...';
    try{
      const chk=await fetch('/api/interactive/ws?check=1&role=teacher');
      const chkData=await chk.json().catch(()=>({ok:false,error:'پاسخ نامعتبر از سرور'}));
      if(!chkData.ok){
        document.getElementById('ia-status').textContent='خطا: '+chkData.error;
        startBtn.disabled=false;
        rmAutoFail('ia','btn-ia-start');
        toast(chkData.error);
        return;
      }
    }catch(e){
      document.getElementById('ia-status').textContent='خطا در ارتباط با سرور';
      startBtn.disabled=false;
      rmAutoFail('ia','btn-ia-start');
      return;
    }
    startBtn.disabled=false;
    const proto=location.protocol==='https:'?'wss:':'ws:';
    iaWs=new WebSocket(proto+'//'+location.host+'/api/interactive/ws?role=teacher&name='+encodeURIComponent('معلم'));
    const myWs=iaWs;
    iaWs.onopen=()=>{RM.ia.ever=true;RM.ia.retry=0;RM.ia.inAuto=false;rmStartHb('ia',function(){return iaWs;});
      document.getElementById('iadot').classList.add('on');
      document.getElementById('ia-status').textContent='تماس تعاملی فعال است ✅';
      document.getElementById('btn-ia-start').classList.add('hidden');
      document.getElementById('btn-ia-stop').classList.remove('hidden');
      document.getElementById('btn-ia-mic-toggle').classList.remove('hidden');
      document.getElementById('btn-ia-cam-toggle').classList.remove('hidden');
      iaSpeakRequests={};iaAllowedSpeakers={};iaRenderSpeakRequests();iaRenderAllowedSpeakers();
      toast('تماس تعاملی شروع شد');
    };
    iaWs.onclose=()=>{
      rmStopHb('ia');
      if(rmReconnect('ia',myWs===iaWs,'iadot','ia-status','btn-ia-start')) return;
      document.getElementById('iadot').classList.remove('on');
      document.getElementById('ia-status').textContent='تماس تعاملی شروع نشده';
      document.getElementById('btn-ia-start').classList.remove('hidden');
      document.getElementById('btn-ia-stop').classList.add('hidden');
      document.getElementById('btn-ia-mic-toggle').classList.add('hidden');
      document.getElementById('btn-ia-cam-toggle').classList.add('hidden');
    };
    iaWs.onmessage=(evt)=>{
      rmTouch('ia');
      let m;try{m=JSON.parse(evt.data);}catch(e){return;}
      if(m.type==='pong') return;
      if(m.type==='init'){
        if(m.boardBg){iaSetBoardBgAndReplay(m.boardBg,m.strokes||[]);}
        else{iaCtx.clearRect(0,0,iaBoard.width,iaBoard.height);iaBoardBgImg=null;(m.strokes||[]).forEach(iaDrawLocal);}
        (m.chat||[]).forEach(iaAddChat);iaUpdateParticipants(m.participants||[]);
        iaAllowedSpeakers={}; (m.speakers||[]).forEach(function(sp){iaAllowedSpeakers[sp.id]=sp.name;}); iaRenderAllowedSpeakers();
      }
      else if(m.type==='chat'){iaAddChat(m.entry);}
      else if(m.type==='file'){iaAddFile(m);}
      else if(m.type==='board-bg'){iaSetBoardBg(m.data);}
      else if(m.type==='error'){toast(m.message||'خطا');}
      else if(m.type==='presence'){iaUpdateParticipants(m.participants||[]);if(m.event==='join'&&m.role==='student')toast((m.count>1?(m.name+' و '+(m.count-1)+' نفر دیگر'):m.name)+' وارد شد');}
      else if(m.type==='raise-hand'){toast('✋ '+m.name+' دستش را بلند کرد');}
      else if(m.type==='speak-request'){ iaSpeakRequests[m.id]=m.name||'دانش‌آموز'; iaRenderSpeakRequests(); toast('✋ '+(m.name||'دانش‌آموز')+' درخواست ورود به تماس داد'); }
      else if(m.type==='video-frame' && m.role==='student'){
        const t=iaEnsureCamTile(m.id, m.from);
        __vid.show(t.img,m.data,function(){__vid.ack(iaWs,m.id||'s');});
        t.img.classList.remove('hidden');
        t.off.classList.add('hidden');
      }
      else if(m.type==='video-stop' && m.role==='student'){
        const t=iaParticipantCamTiles[m.id];
        if(t){ t.img.classList.add('hidden'); __vid.reset(t.img);t.img.src=''; t.off.classList.remove('hidden'); }
      }
      else if(m.type==='audio' && m.role==='student'){
        iaPlayParticipantAudio(m.id, m.data, m.mime, m);
      }
    };
  };
  document.getElementById('btn-ia-stop').onclick=()=>{
    RM.ia.stopping=true;
    if(iaRecorder&&iaRecorder.state!=='inactive')iaRecorder.stop();
    if(iaMicStream)iaMicStream.getTracks().forEach(t=>t.stop());
    iaMicStream=null;
    document.getElementById('btn-ia-mic-toggle').textContent='🎙️ روشن کردن میکروفون';
    if(iaCamStream){iaCamStream.getTracks().forEach(t=>t.stop());iaCamStream=null;}
    if(iaCamInterval){clearInterval(iaCamInterval);iaCamInterval=null;}
    document.getElementById('ia-cam-preview').classList.add('hidden');
    document.getElementById('ia-cam-preview').srcObject=null;
    document.getElementById('ia-cam-off').classList.remove('hidden');
    document.getElementById('btn-ia-cam-toggle').textContent='📷 روشن کردن تصویر';
    document.getElementById('btn-ia-cam-flip').classList.add('hidden');
    iaCamFacing='user';
    iaAudioFromCam=false;
    if(iaWs)iaWs.close();
    clearActiveCameraFeature('interactive');
  };

  document.getElementById('btn-ia-options-toggle').onclick=function(){
    document.getElementById('ia-options-drawer').classList.toggle('hidden');
  };

  function iaStartMicRecorder(stream){
    if(iaAudioActive) return; // جلوگیری از راه‌اندازی دوباره و همپوشانی صدا (علت اصلی تکرار صدا)
    iaMicStream=stream;
    iaAudioActive=true;
    iaAudioGen++;
    const myGen=iaAudioGen;
    const preferredMimes=['audio/webm;codecs=opus','audio/webm','audio/mp4'];
    const mime=preferredMimes.find(m=>window.MediaRecorder && MediaRecorder.isTypeSupported(m)) || '';
    const CLIP_S=0.35, LEAD_S=0.10, TAIL_S=0.04, T0_MS=performance.now();
      function recordOneChunk(k){
        k=k||0;
      if(myGen!==iaAudioGen || !iaAudioActive || !iaMicStream) return;
      let chunks=[];
      let rec;
      try{ rec=new MediaRecorder(iaMicStream, mime?{mimeType:mime}:undefined); }
      catch(e){ iaAudioActive=false; toast('امکان ضبط صدا در این مرورگر نیست'); return; }
      rec.ondataavailable=(e)=>{ if(e.data && e.data.size>0) chunks.push(e.data); };
      rec.onstop=async()=>{
        if(myGen!==iaAudioGen) return;
        if(chunks.length){
          const blob=new Blob(chunks, {type: mime||'audio/webm'});
          const buf=await blob.arrayBuffer();
          let binary='';const bytes=new Uint8Array(buf);
          for(let i=0;i<bytes.length;i++)binary+=String.fromCharCode(bytes[i]);
          iaSend({type:'audio', data: btoa(binary), mime: mime||'audio/webm', lead: rec._lead||0, len: CLIP_S});
        }
      };
      rec.start();
      iaRecorder=rec;
      rec._lead=(k===0)?0:LEAD_S;
      // ضبط هر تکه LEAD_S ثانیه زودتر از مرز شروع می‌شود و TAIL_S ثانیه دیرتر تمام می‌شود (همپوشانی)؛ گیرنده فقط بخش اصلی را پخش می‌کند
      const endAt=T0_MS+(k+1)*CLIP_S*1000;
      setTimeout(()=>{ if(rec.state==='recording') rec.stop(); }, Math.max(0,endAt+TAIL_S*1000-performance.now()));
      setTimeout(()=>{ recordOneChunk(k+1); }, Math.max(0,endAt-LEAD_S*1000-performance.now()));
    }
    recordOneChunk();
  }
  function iaStopMicRecorder(){
    iaAudioActive=false;
    iaAudioGen++; // هر حلقه‌ی در حال اجرا با چک نسل، خودش را متوقف می‌کند
    if(iaRecorder && iaRecorder.state==='recording')iaRecorder.stop();
    if(iaMicStream)iaMicStream.getTracks().forEach(t=>t.stop());
    iaMicStream=null;
    document.getElementById('btn-ia-mic-toggle').textContent='🎙️ روشن کردن میکروفون';
  }

  document.getElementById('btn-ia-mic-toggle').onclick=async function(){
    if(iaRecorder && iaRecorder.state==='recording'){
      iaStopMicRecorder();
      iaAudioFromCam=false;
      return;
    }
    try{
      const stream=await navigator.mediaDevices.getUserMedia({audio:true});
      iaStartMicRecorder(stream);
      iaAudioFromCam=false;
      this.textContent='🔴 خاموش کردن میکروفون';
      toast('میکروفون فعال شد');
    }catch(e){ toast('دسترسی به میکروفون داده نشد'); }
  };

  document.getElementById('btn-ia-cam-toggle').onclick=async function(){
    const preview=document.getElementById('ia-cam-preview');
    if(iaCamStream){
      iaCamStream.getVideoTracks().forEach(t=>t.stop());
      iaCamStream=null;
      if(iaCamInterval){clearInterval(iaCamInterval);iaCamInterval=null;}
      preview.classList.add('hidden');
      preview.srcObject=null;
      document.getElementById('ia-cam-off').classList.remove('hidden');
      this.textContent='📷 روشن کردن تصویر';
      document.getElementById('btn-ia-cam-flip').classList.add('hidden');
      iaCamFacing='user';
      iaSend({type:'video-stop'});
      if(iaAudioFromCam){ iaStopMicRecorder(); iaAudioFromCam=false; }
      clearActiveCameraFeature('interactive');
      return;
    }
    try{
      warnIfOtherCameraActive('interactive','تماس تعاملی');
      // نکته: عمداً فقط عرض تقریبی درخواست می‌شود، نه عرض+ارتفاع با هم؛ وقتی هر دو با هم
      // درخواست شوند و با نسبت واقعی دوربین گوشی جور نباشد، خیلی از گوشی‌های اندروید به‌جای
      // برش تصویر، دور آن را با نوار سیاه پر می‌کنند و تصویر خیلی کوچک و وسط‌چین دیده می‌شود.
      iaCamStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:iaCamFacing,width:{ideal:480}}, audio:true});
      preview.srcObject=iaCamStream;
      preview.classList.remove('hidden');
      document.getElementById('ia-cam-off').classList.add('hidden');
      iaUpdateCamLayout();
      this.textContent='🔴 خاموش کردن تصویر';
      document.getElementById('btn-ia-cam-flip').classList.remove('hidden');
      // اگر میکروفون از قبل روشن نبود، صدا را هم همراه تصویر روشن کن (مثل یک تماس تصویری واقعی)
      if(!(iaRecorder && iaRecorder.state==='recording') && iaCamStream.getAudioTracks().length){
        iaStartMicRecorder(new MediaStream(iaCamStream.getAudioTracks()));
        iaAudioFromCam=true;
        document.getElementById('btn-ia-mic-toggle').textContent='🔴 خاموش کردن میکروفون';
      }
      toast('تماس تصویری (با صدا) فعال شد');
      const cap=document.createElement('canvas');
      const capCtx=cap.getContext('2d');
      const __vs=__vid.newSender();
      iaCamInterval=setInterval(function(){ if(!iaCamStream)return; __vid.tick(__vs,preview,iaWs); },50); // ارسال تطبیقی: کیفیت/اندازه/نرخ فریم خودکار با وضعیت شبکه تنظیم می‌شود
    }catch(e){ toast('دسترسی به دوربین یا میکروفون داده نشد'); }
  };

  document.getElementById('btn-ia-cam-flip').onclick=async function(){
    if(!iaCamStream){toast('ابتدا دوربین را روشن کنید');return;}
    const preview=document.getElementById('ia-cam-preview');
    const prevFacing=iaCamFacing;
    const nextFacing=iaCamFacing==='user'?'environment':'user';
    const wasAudioFromCam=iaAudioFromCam;
    if(wasAudioFromCam){ iaStopMicRecorder(); iaAudioFromCam=false; }
    // دوربین فعلی را قبل از درخواست دوربین جدید کاملاً آزاد می‌کنیم؛ خیلی از مرورگرها/دستگاه‌ها
    // اجازه نمی‌دهند دو دوربین همزمان باز باشند و همین باعث می‌شد چرخش دوربین کار نکند.
    iaCamStream.getTracks().forEach(t=>t.stop());
    iaCamStream=null;
    preview.srcObject=null;
    try{
      const newStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{exact:nextFacing},width:{ideal:480}}, audio:true});
      iaCamStream=newStream;
      iaCamFacing=nextFacing;
      preview.srcObject=iaCamStream;
      if(wasAudioFromCam && iaCamStream.getAudioTracks().length){
        iaStartMicRecorder(new MediaStream(iaCamStream.getAudioTracks()));
        iaAudioFromCam=true;
        document.getElementById('btn-ia-mic-toggle').textContent='🔴 خاموش کردن میکروفون';
      }
      toast('دوربین عوض شد 🔄');
    }catch(e){
      toast('این دستگاه دوربین دومی ندارد یا اجازه دسترسی به آن را نمی‌دهد');
      // تلاش برای بازگرداندن دوربین قبلی تا تصویر کلاً قطع نشود
      try{
        iaCamStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:prevFacing,width:{ideal:480}}, audio:true});
        iaCamFacing=prevFacing;
        preview.srcObject=iaCamStream;
        if(wasAudioFromCam && iaCamStream.getAudioTracks().length){
          iaStartMicRecorder(new MediaStream(iaCamStream.getAudioTracks()));
          iaAudioFromCam=true;
          document.getElementById('btn-ia-mic-toggle').textContent='🔴 خاموش کردن میکروفون';
        }
      }catch(e2){
        toast('دسترسی به دوربین قطع شد؛ لطفاً دوباره روی «روشن کردن تصویر» بزنید');
        document.getElementById('btn-ia-cam-toggle').textContent='📷 روشن کردن تصویر';
        document.getElementById('btn-ia-cam-flip').classList.add('hidden');
      }
    }
  };


  // ===================== حضور و غیاب (چند لیست/لینک جدا؛ هر لیست ثبت‌نامش را دارد) =====================

  // --- زیرتب‌های داخلی حضور و غیاب (ورود دستی / ساخت لینک) ---
  (function(){
    var tabs=document.querySelectorAll('.att-inner-tab');
    tabs.forEach(function(tab){
      tab.onclick=function(){
        tabs.forEach(function(t){
          t.classList.remove('active');
          t.style.background='';
          t.style.borderBottom='';
          t.style.color='';
        });
        tab.classList.add('active');
        var pane=tab.dataset.attItab;
        document.getElementById('att-pane-manual').classList.toggle('hidden', pane!=='manual');
        document.getElementById('att-pane-link').classList.toggle('hidden', pane!=='link');
        if(pane==='link'&&!attLinksLoaded){attLoadLinks();}
        if(pane==='manual'){attMRefreshListSelect();}
      };
    });
  })();

  // --- ورود دستی: مدیریت لیست انتخابی ---
  var ATT_M_SELECTED_LINK=null;
  var attMLastRecords=[];

  function attMRefreshListSelect(){
    // از همان ATT_LINKS استفاده می‌کنیم — اگر لود نشده بود، لود می‌کنیم
    if(!attLinksLoaded){ attLoadLinks().then(attMPopulateSelect); return; }
    attMPopulateSelect();
  }
  function attMPopulateSelect(){
    var sel=document.getElementById('att-m-list-select');
    if(!sel)return;
    sel.innerHTML='<option value="">— ابتدا یک لیست انتخاب یا بسازید —</option>';
    ATT_LINKS.forEach(function(l){
      var opt=document.createElement('option');
      opt.value=l.id;
      opt.textContent=(l.title||'بدون عنوان')+' ('+(l.count||0)+' نفر)';
      if(l.id===ATT_M_SELECTED_LINK)opt.selected=true;
      sel.appendChild(opt);
    });
  }
  document.getElementById('att-m-list-select').onchange=function(){
    ATT_M_SELECTED_LINK=this.value||null;
    if(ATT_M_SELECTED_LINK){
      var link=ATT_LINKS.find(function(l){return l.id===ATT_M_SELECTED_LINK;});
      document.getElementById('att-m-selected-title').textContent='فهرست: '+(link?link.title:'');
      document.getElementById('att-m-selected-wrap').classList.remove('hidden');
      attMLastRecords=[];
      attMRenderTable();
      document.getElementById('btn-att-m-refresh').click();
    }else{
      document.getElementById('att-m-selected-wrap').classList.add('hidden');
    }
  };
  document.getElementById('btn-att-m-create-list').onclick=async function(){
    var inp=document.getElementById('att-m-new-title');
    var title=inp.value.trim();
    if(!title){toast('یک عنوان برای لیست وارد کنید');return;}
    this.disabled=true;
    var d=await api('/api/teacher/attendance-links',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({title:title})});
    this.disabled=false;
    if(d&&d.ok){
      inp.value='';
      toast('لیست ساخته شد ✅');
      await attLoadLinks();
      attMPopulateSelect();
      if(d.link&&d.link.id){
        ATT_M_SELECTED_LINK=d.link.id;
        document.getElementById('att-m-list-select').value=d.link.id;
        document.getElementById('att-m-list-select').dispatchEvent(new Event('change'));
      }
    }else toast((d&&d.error)||'خطا در ساخت لیست');
  };
  document.getElementById('btn-att-m-del-list').onclick=async function(){
    if(!ATT_M_SELECTED_LINK){toast('ابتدا یک لیست انتخاب کنید');return;}
    var link=ATT_LINKS.find(function(l){return l.id===ATT_M_SELECTED_LINK;});
    var title=link?link.title:'این لیست';
    if(!confirm('لیست «'+title+'» و همه‌ی ثبت‌نام‌های آن حذف شود؟ این کار قابل بازگشت نیست.'))return;
    this.disabled=true;
    var d=await api('/api/teacher/attendance-links/'+encodeURIComponent(ATT_M_SELECTED_LINK),{method:'DELETE'});
    this.disabled=false;
    if(d&&d.ok){
      toast('لیست حذف شد ✅');
      ATT_M_SELECTED_LINK=null;
      attMLastRecords=[];
      document.getElementById('att-m-selected-wrap').classList.add('hidden');
      await attLoadLinks();
      attMPopulateSelect();
    }else toast((d&&d.error)||'خطا در حذف لیست');
  };
  function attMRenderTable(){
    var wrap=document.getElementById('att-m-records-wrap');
    if(!wrap)return;
    if(!attMLastRecords.length){ wrap.innerHTML='<span class="muted">هنوز کسی ثبت نشده است</span>'; return; }
    wrap.innerHTML='<table><tr><th>نام</th><th>نام خانوادگی</th><th>سمت</th><th>کد ملی</th><th>مدرسه</th><th>منطقه</th><th>زمان</th><th></th></tr>'+
      attMLastRecords.map(function(r){return '<tr><td>'+esc(r.name||'')+'</td><td>'+esc(r.family||'')+'</td><td>'+esc(r.role||'—')+'</td><td>'+esc(r.nationalCode||'')+'</td><td>'+esc(r.school||'')+'</td><td>'+esc(r.region||'')+'</td><td>'+attFmtTime(r.ts)+'</td><td><button class="btn sm danger" type="button" data-attm-del="'+esc(r.id||'')+'">🗑 حذف</button></td></tr>';}).join('')+
      '</table>';
  }
  document.getElementById('btn-att-m-refresh').onclick=async function(){
    if(!ATT_M_SELECTED_LINK){toast('ابتدا یک لیست انتخاب کنید');return;}
    var d=await api('/api/teacher/attendance?linkId='+encodeURIComponent(ATT_M_SELECTED_LINK));
    if(d&&d.ok){attMLastRecords=d.records||[];attMRenderTable();}
    else toast((d&&d.error)||'خطا در بارگذاری');
  };
  document.getElementById('att-m-records-wrap').addEventListener('click',async function(e){
    var btn=e.target.closest('[data-attm-del]');
    if(!btn)return;
    if(!confirm('این رکورد حذف شود؟'))return;
    btn.disabled=true;
    var id=btn.dataset.attmDel;
    var d=await api('/api/teacher/attendance-record/'+encodeURIComponent(id),{method:'DELETE'});
    if(d&&d.ok){attMLastRecords=attMLastRecords.filter(function(r){return r.id!==id;});attMRenderTable();}
    else{btn.disabled=false;toast((d&&d.error)||'خطا در حذف');}
  });
  // دکمه‌های Excel/Word/PDF/لوح تقدیر زیرتب دستی — از همان توابع زیرتب لینک استفاده می‌شود
  document.getElementById('btn-att-m-save').onclick=async function(){
    if(!ATT_M_SELECTED_LINK){toast('ابتدا یک لیست انتخاب کنید');return;}
    // رکوردهای فعلی را از سرور دوباره می‌گیریم تا مطمئن شویم جدیدترین حالت ذخیره است
    var btn=this; btn.disabled=true;
    var d=await api('/api/teacher/attendance?linkId='+encodeURIComponent(ATT_M_SELECTED_LINK));
    btn.disabled=false;
    if(d&&d.ok){
      attMLastRecords=d.records||[];
      attMRenderTable();
      toast('لیست ذخیره و بروزرسانی شد ✅ ('+attMLastRecords.length+' نفر)');
    }else toast((d&&d.error)||'خطا در ذخیره');
  };
  document.getElementById('btn-att-m-excel').onclick=function(){if(!ATT_M_SELECTED_LINK){toast('ابتدا یک لیست انتخاب کنید');return;} attExportExcel(attMLastRecords);};
  document.getElementById('btn-att-m-word').onclick=function(){if(!ATT_M_SELECTED_LINK){toast('ابتدا یک لیست انتخاب کنید');return;} attExportWord(attMLastRecords,document.getElementById('att-m-selected-title').textContent);};
  document.getElementById('btn-att-m-pdf').onclick=function(){if(!ATT_M_SELECTED_LINK){toast('ابتدا یک لیست انتخاب کنید');return;} attExportPdf(attMLastRecords,document.getElementById('att-m-selected-title').textContent);};
  document.getElementById('btn-att-m-send-cert').onclick=async function(){
    if(!ATT_M_SELECTED_LINK){toast('ابتدا یک لیست انتخاب کنید');return;}
    // اگر هنوز رکوردها لود نشده، اول لود کن
    if(!attMLastRecords.length){
      var d=await api('/api/teacher/attendance?linkId='+encodeURIComponent(ATT_M_SELECTED_LINK));
      if(!d||!d.ok){toast((d&&d.error)||'خطا در دریافت اطلاعات');return;}
      attMLastRecords=d.records||[];
      attMRenderTable();
    }
    if(!attMLastRecords.length){toast('هنوز کسی در این لیست ثبت نشده است');return;}
    // همگام‌سازی ATT_SELECTED_LINK تا توابع لوح تقدیر بدانند کدام لیست انتخاب است
    ATT_SELECTED_LINK=ATT_M_SELECTED_LINK;
    attLastRecords=attMLastRecords.slice();
    WBC_ATTENDEES_LOADED=false;
    try{
      await wbcPopulateAttLinkSelect(true);
      await certCollPopulateAttLinkSelect(true);
      ['wbc-attlink-select','cert-colllink-select'].forEach(function(id){
        var sel=document.getElementById(id);
        if(sel){sel.value=ATT_M_SELECTED_LINK;try{sel.dispatchEvent(new Event('change'));}catch(e){}}
      });
    }catch(e){}
    toast(attMLastRecords.length+' نفر آماده‌ی صدور گواهی شدند — در حال انتقال...');
    setTimeout(function(){location.href='/teacher?tab=schedule&subtab=sch-webinar';},900);
  };

  function attFmtTime(ts){
    try{ return new Date(ts).toLocaleString('fa-IR'); }catch(e){ return ''; }
  }
  function attLinkUrl(id){ return location.origin+(id==='default'?'/class/attendance':'/class/attendance/'+id); }
  var ATT_LINKS=[];
  var ATT_SELECTED_LINK=null;
  var attLinksLoaded=false;
  async function attLoadLinks(){
    var wrap=document.getElementById('att-links-wrap');
    wrap.innerHTML='<span class="muted">در حال بارگذاری لیست‌ها...</span>';
    var d=await api('/api/teacher/attendance-links');
    if(!d || !d.ok){ wrap.innerHTML='<span class="muted">'+((d&&d.error)||'خطا در دریافت لیست‌ها')+'</span>'; return; }
    ATT_LINKS=d.links||[];
    attLinksLoaded=true;
    attRenderLinks();
    if(typeof attMPopulateSelect==='function')attMPopulateSelect();
  }
  function attRenderLinks(){
    var wrap=document.getElementById('att-links-wrap');
    if(!ATT_LINKS.length){ wrap.innerHTML='<span class="muted">هنوز لیستی نساخته‌اید. یک عنوان بنویسید و «ساخت لیست جدید» را بزنید.</span>'; return; }
    wrap.innerHTML=ATT_LINKS.map(function(l){
      var url=attLinkUrl(l.id);
      var active=(ATT_SELECTED_LINK===l.id)?' style="border:2px solid var(--primary)"':'';
      return '<div class="card" data-att-card="'+esc(l.id)+'"'+active+' style="padding:10px 14px;margin-bottom:8px;background:var(--soft)">'
        +'<div class="row" style="align-items:center;gap:8px;flex-wrap:wrap">'
        +'<b style="flex:1">'+esc(l.title||'بدون عنوان')+'</b>'
        +'<span class="muted" style="font-size:11px;background:#fff;border:1px solid var(--line);border-radius:6px;padding:2px 6px">#'+esc(l.shortId||'')+'</span>'
        +'<span class="muted" style="font-size:12px">'+(l.count||0)+' نفر ثبت‌نام</span>'
        +'</div>'
        +'<div class="row" style="align-items:center;gap:8px;margin-top:8px;flex-wrap:wrap">'
        +'<div class="link-box" style="flex:1;min-width:180px;font-size:12px">'+esc(url)+'</div>'
        +'<button type="button" class="btn sm sec" data-att-copy="'+esc(url)+'" style="flex:0 0 auto">کپی لینک</button>'
        +'<button type="button" class="btn sm" data-att-view="'+esc(l.id)+'" style="flex:0 0 auto">👁️ مشاهده لیست</button>'
        +'<button type="button" class="btn sm danger" data-att-link-del="'+esc(l.id)+'" style="flex:0 0 auto">🗑 حذف لیست</button>'
        +'</div></div>';
    }).join('');
  }
  function attSelectLink(id){
    ATT_SELECTED_LINK=id;
    attRenderLinks();
    var link=ATT_LINKS.find(function(l){return l.id===id;});
    document.getElementById('att-selected-wrap').classList.remove('hidden');
    document.getElementById('att-selected-title').textContent='فهرست ثبت‌نام‌ها: '+(link?link.title:'');
    attLastRecords=[];
    attRenderTable();
    document.getElementById('btn-att-refresh').click();
  }
  document.getElementById('btn-att-link-create').onclick=async function(){
    var titleInp=document.getElementById('att-new-title');
    var title=titleInp.value.trim();
    if(!title){toast('یک عنوان برای لیست وارد کنید');return;}
    this.disabled=true;
    var d=await api('/api/teacher/attendance-links',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({title:title})});
    this.disabled=false;
    if(d && d.ok){ titleInp.value=''; toast('لیست ساخته شد ✅'); await attLoadLinks(); if(d.link&&d.link.id)attSelectLink(d.link.id); }
    else toast((d&&d.error)||'خطا در ساخت لیست');
  };
  document.getElementById('att-links-wrap').addEventListener('click',async function(e){
    var copyBtn=e.target.closest('[data-att-copy]');
    if(copyBtn){ copyLink(copyBtn.dataset.attCopy); return; }
    var viewBtn=e.target.closest('[data-att-view]');
    if(viewBtn){ attSelectLink(viewBtn.dataset.attView); return; }
    var delBtn=e.target.closest('[data-att-link-del]');
    if(delBtn){
      if(!confirm('این لیست و همه‌ی ثبت‌نام‌های آن حذف شود؟ این کار قابل بازگشت نیست.'))return;
      delBtn.disabled=true;
      var id=delBtn.dataset.attLinkDel;
      var d=await api('/api/teacher/attendance-links/'+encodeURIComponent(id),{method:'DELETE'});
      if(d && d.ok){
        toast('لیست حذف شد ✅');
        if(ATT_SELECTED_LINK===id){ ATT_SELECTED_LINK=null; document.getElementById('att-selected-wrap').classList.add('hidden'); }
        await attLoadLinks();
      }else{ delBtn.disabled=false; toast((d&&d.error)||'خطا در حذف'); }
    }
  });
  let attLastRecords=[];
  /* حالت چسبان خودکار: سربرگ جدول هنگام اسکرول بالای کادر ثابت می‌ماند (قابل خاموش/روشن کردن) */
  function attApplySticky(){
    const wrap=document.getElementById('att-records-wrap');
    const tog=document.getElementById('att-sticky-toggle');
    if(!wrap)return;
    if(tog&&tog.checked)wrap.classList.add('att-sticky-wrap');
    else wrap.classList.remove('att-sticky-wrap');
  }
  (function(){
    const tog=document.getElementById('att-sticky-toggle');
    if(tog)tog.addEventListener('change',attApplySticky);
  })();
  function attRenderTable(){
    const wrap=document.getElementById('att-records-wrap');
    if(!attLastRecords.length){ wrap.classList.remove('att-sticky-wrap'); wrap.innerHTML='<span class="muted">هنوز کسی این فرم را ثبت نکرده است</span>'; return; }
    wrap.innerHTML='<table><tr><th>نام</th><th>نام خانوادگی</th><th>سمت</th><th>کد ملی</th><th>مدرسه</th><th>منطقه</th><th>زمان</th><th></th></tr>'+
      attLastRecords.map(r=>'<tr><td>'+esc(r.name||'')+'</td><td>'+esc(r.family||'')+'</td><td>'+esc(r.role||'—')+'</td><td>'+esc(r.nationalCode||'')+'</td><td>'+esc(r.school||'')+'</td><td>'+esc(r.region||'')+'</td><td>'+attFmtTime(r.ts)+'</td><td><button class="btn sm danger" type="button" data-att-del="'+esc(r.id||'')+'">🗑 حذف</button></td></tr>').join('')+
      '</table>';
    attApplySticky();
  }
  /* افزودن دستی اطلاعات پرسنل: رکورد در همان لیست انتخاب‌شده ذخیره می‌شود، بنابراین
     به‌طور خودکار در فهرست انتخاب «لوح تقدیر» و «گواهی حضور در وبینار» هم ظاهر می‌شود. */
  function attManualVal(id){var el=document.getElementById(id);return el?String(el.value||'').trim():'';}
  function attManualClear(){
    ['att-m-name','att-m-family','att-m-school','att-m-region','att-m-role','att-m-code'].forEach(function(id){
      var el=document.getElementById(id); if(el)el.value='';
    });
  }
  // ===================== جدول ورود دستی اطلاعات (جدول اکسل‌مانند با سربرگ ثابت) =====================
  // fullname = نام و نام خانوادگی ترکیبی؛ هنگام ثبت به name/family تقسیم می‌شود
  var ATT_M_TABLE_ROWS=[]; // [{fullname,role,school,region,nationalCode}, ...]
  var ATT_M_TABLE_COLS=['fullname','role','school','region','nationalCode'];
  var ATT_M_TABLE_PLACEHOLDERS=['نام و نام خانوادگی','سمت','مدرسه','منطقه','کد ملی'];

  function attMSplitName(fullname){
    // اولین فاصله را جدا کن: «علی احمدی» → name=علی، family=احمدی
    var s=String(fullname||'').trim();
    var idx=s.indexOf(' ');
    if(idx===-1)return{name:s,family:''};
    return{name:s.slice(0,idx).trim(),family:s.slice(idx+1).trim()};
  }

  function attMTableAddRow(data){
    data=data||{};
    // پشتیبانی از هر دو فرمت: fullname یا name+family جداگانه
    var fn=data.fullname||(data.name&&data.family?(data.name+' '+data.family).trim():data.name||'');
    ATT_M_TABLE_ROWS.push({
      fullname:fn,role:data.role||'',
      school:data.school||'',region:data.region||'',nationalCode:data.nationalCode||''
    });
    attMTableRender();
  }

  function attMTableRender(){
    var tbody=document.getElementById('att-m-input-tbody');
    if(!tbody)return;
    tbody.innerHTML='';
    ATT_M_TABLE_ROWS.forEach(function(row,ri){
      var tr=document.createElement('tr');
      tr.style.background=ri%2===0?'#fff':'#f8fafc';
      // ردیف شماره
      var tdNum=document.createElement('td');
      tdNum.style.cssText='border:1px solid #dde3ec;padding:4px 8px;text-align:center;font-size:12px;color:#888;white-space:nowrap;min-width:36px';
      tdNum.textContent=ri+1;
      tr.appendChild(tdNum);
      // خانه‌های داده
      ATT_M_TABLE_COLS.forEach(function(col,ci){
        var td=document.createElement('td');
        td.style.cssText='border:1px solid #dde3ec;padding:0;min-width:'+(col==='fullname'?'180px':col==='nationalCode'?'110px':'100px');
        var inp=document.createElement('input');
        inp.type=col==='nationalCode'?'tel':'text';
        if(col==='nationalCode')inp.setAttribute('inputmode','numeric');
        inp.value=row[col]||'';
        inp.placeholder=ATT_M_TABLE_PLACEHOLDERS[ci];
        inp.style.cssText='width:100%;border:none;padding:6px 8px;font:inherit;background:transparent;box-sizing:border-box;outline:none';
        inp.dataset.row=ri; inp.dataset.col=col;
        inp.addEventListener('input',function(){ATT_M_TABLE_ROWS[+this.dataset.row][this.dataset.col]=this.value;});
        // چسباندن هوشمند از اکسل در هر خانه
        inp.addEventListener('paste',function(e){
          var text=(e.clipboardData||window.clipboardData).getData('text');
          if(!text)return;
          var NL=String.fromCharCode(10),CR=String.fromCharCode(13),TAB=String.fromCharCode(9);
          var lines=text.split(CR).join('').split(NL);
          while(lines.length>1&&lines[lines.length-1]==='')lines.pop();
          var grid=lines.map(function(l){return l.split(TAB);});
          var isMulti=grid.length>1||(grid[0]&&grid[0].length>1);
          if(!isMulti)return;
          e.preventDefault();
          var startRow=+this.dataset.row;
          var startCol=ATT_M_TABLE_COLS.indexOf(this.dataset.col);
          // سطرهای لازم اضافه کن
          var needed=startRow+grid.length;
          while(ATT_M_TABLE_ROWS.length<needed)ATT_M_TABLE_ROWS.push({fullname:'',role:'',school:'',region:'',nationalCode:''});
          grid.forEach(function(rowArr,gi){
            rowArr.forEach(function(val,ci){
              var colIdx=startCol+ci;
              if(colIdx<ATT_M_TABLE_COLS.length)ATT_M_TABLE_ROWS[startRow+gi][ATT_M_TABLE_COLS[colIdx]]=String(val||'').trim();
            });
          });
          attMTableRender();
          toast('چسبانده شد: '+grid.length+' ردیف ✅');
        });
        // Tab برای رفتن به خانه بعدی
        inp.addEventListener('keydown',function(e){
          if(e.key==='Tab'&&!e.shiftKey){
            var ri2=+this.dataset.row,ci2=ATT_M_TABLE_COLS.indexOf(this.dataset.col);
            var nextCi=ci2+1;
            if(nextCi>=ATT_M_TABLE_COLS.length){nextCi=0;ri2++;}
            if(ri2>=ATT_M_TABLE_ROWS.length){attMTableAddRow();return;}
            e.preventDefault();
            var all=document.querySelectorAll('#att-m-input-tbody input[data-row="'+ri2+'"][data-col="'+ATT_M_TABLE_COLS[nextCi]+'"]');
            if(all[0])all[0].focus();
          }
          if(e.key==='Enter'){
            // رفتن به سطر بعدی، همان ستون
            var ri3=+this.dataset.row+1;
            if(ri3>=ATT_M_TABLE_ROWS.length){attMTableAddRow();return;}
            e.preventDefault();
            var all2=document.querySelectorAll('#att-m-input-tbody input[data-row="'+ri3+'"][data-col="'+this.dataset.col+'"]');
            if(all2[0])all2[0].focus();
          }
        });
        td.appendChild(inp);
        tr.appendChild(td);
      });
      tbody.appendChild(tr);
    });
  }

  // مقداردهی اولیه با ۵ سطر خالی
  (function(){for(var i=0;i<5;i++)ATT_M_TABLE_ROWS.push({fullname:'',role:'',school:'',region:'',nationalCode:''});attMTableRender();})();

  document.getElementById('btn-att-m-addrow').onclick=function(){attMTableAddRow();};
  document.getElementById('btn-att-m-delrow').onclick=function(){
    if(ATT_M_TABLE_ROWS.length<=1){toast('حداقل یک سطر باید باقی بماند');return;}
    ATT_M_TABLE_ROWS.pop();attMTableRender();
  };
  document.getElementById('btn-att-manual-clear').onclick=function(){
    if(!confirm('همه سطرهای جدول پاک شود؟'))return;
    ATT_M_TABLE_ROWS=[];
    for(var i=0;i<5;i++)ATT_M_TABLE_ROWS.push({fullname:'',role:'',school:'',region:'',nationalCode:''});
    attMTableRender();
    toast('جدول پاک شد');
  };

  function attManualVal(id){
    // سازگاری با کدهای قدیمی که از input id استفاده می‌کردند
    var el=document.getElementById(id);return el?String(el.value||'').trim():'';
  }
  function attManualClear(){
    ATT_M_TABLE_ROWS=[];
    for(var i=0;i<5;i++)ATT_M_TABLE_ROWS.push({fullname:'',role:'',school:'',region:'',nationalCode:''});
    attMTableRender();
  }

  document.getElementById('btn-att-manual-add').onclick=async function(){
    var targetLink=ATT_M_SELECTED_LINK||ATT_SELECTED_LINK;
    if(!targetLink){toast('ابتدا یک لیست را انتخاب کنید');return;}
    var rows=ATT_M_TABLE_ROWS.filter(function(r){return (r.fullname||'').trim();});
    if(!rows.length){toast('حداقل یک سطر با نام و نام خانوادگی پر کنید');return;}
    var btn=this; btn.disabled=true;
    toast('در حال ثبت '+rows.length+' ردیف...');
    // ارسال دسته‌ای (batch) به جای یک‌به‌یک — بسیار سریع‌تر
    var payload=rows.map(function(r){
      var nm=attMSplitName(r.fullname);
      return {linkId:targetLink,name:nm.name,family:nm.family,role:r.role||'',school:r.school||'',region:r.region||'',nationalCode:r.nationalCode||''};
    });
    var d=await api('/api/teacher/attendance-manual-batch',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({rows:payload})});
    if(d&&d.ok){
      var added=d.added||0, failed=d.failed||0;
      // رکوردهای جدید را به لیست محلی اضافه کن
      if(d.results){
        d.results.forEach(function(r){
          if(r.ok&&r.record){
            if(targetLink===ATT_M_SELECTED_LINK)attMLastRecords.unshift(r.record);
            if(targetLink===ATT_SELECTED_LINK)attLastRecords.unshift(r.record);
          }
        });
      }
      if(targetLink===ATT_M_SELECTED_LINK)attMRenderTable();
      if(targetLink===ATT_SELECTED_LINK)attRenderTable();
      attManualClear();
      WBC_ATTENDEES_LOADED=false;
      btn.disabled=false;
      toast(added+' ردیف ثبت شد ✅'+(failed?(' — '+failed+' ردیف ناموفق'):''));
    }else{
      btn.disabled=false;
      toast((d&&d.error)||'خطا در ثبت اطلاعات');
    }
  };
  // ===================== پایان جدول ورود دستی اطلاعات =====================
  /* «ارسال به لوح تقدیر و گواهی وبینار»: فهرست را تازه می‌کند و کاربر را به آن تب می‌برد،
     با همان لیست حضور و غیاب از‌پیش‌انتخاب‌شده تا فقط افراد را تیک بزند و گواهی صادر کند. */
