        var g=idx+1;
        var b=parseInt(toEnDigits(document.querySelector('.lbg-boy[data-grade="'+g+'"]').value),10)||0;
        var gi=parseInt(toEnDigits(document.querySelector('.lbg-girl[data-grade="'+g+'"]').value),10)||0;
        totalBoy+=b;totalGirl+=gi;
