  // ===================== درصد قبولی دانش‌آموزان =====================
  var LBPR_GRADE_NAMES=['اول','دوم','سوم','چهارم','پنجم','ششم'];
  var LBPR_LEGACY_FONT={'default':'Vazirmatn','titr':'B Titr','nazanin':'B Nazanin','mitra':'B Mitra'};
  // تم‌های رنگی نمودار و جدول (همه ملایم؛ تم «وضعیتی» رنگ میله‌ها را بر اساس درصد تعیین می‌کند)
  var PR_THEMES=[
    {id:'status',name:'🚦 وضعیتی (قرمز / آبی / سبز ملایم)',status:true,bars:['#bfdbfe'],head:['#f1eefb','#e3f1fa','#e6f5ec','#fdf3dc'],rule:['#9fc0f0','#c3b3ee'],line:'#5b8def',pass:'#8fd9ac',fail:'#f6c1c1',ink:'#27466f'},
    {id:'rainbow',name:'🌈 رنگین‌کمان ملایم',bars:['#f9bfd3','#fbcfae','#fbe39a','#bfe7cb','#b7dcf6','#d2c6f3'],head:['#fde8f1','#fdf0e1','#eaf6ee','#e8f1fc'],rule:['#f5a9c9','#9fc0f0'],line:'#e58ab0',pass:'#a9dfc0',fail:'#fbd0d9',ink:'#5a3550'},
    {id:'ocean',name:'🌊 آبی اقیانوسی',bars:['#cfe1fa','#b5d0f6','#9abeef','#7fabe8','#6597e0','#4d85d6'],head:['#e8f0fc','#dce9fb','#d0e2f9','#c4dbf7'],rule:['#8fb7ee','#7fd0e8'],line:'#4d85d6',pass:'#7fb2ea',fail:'#e4ebf5',ink:'#24476f'},
    {id:'mint',name:'🍃 سبز نعنایی',bars:['#d3f0df','#bde8d0','#a6dfc0','#90d6b0','#79cca0','#62c190'],head:['#eaf8f0','#dff3e8','#d3eee0','#c8e9d8'],rule:['#8fd9ac','#8fd3e0'],line:'#4fae80',pass:'#79cca0',fail:'#e6efe9',ink:'#25604a'},
    {id:'lavender',name:'🦄 لوندر',bars:['#e4dcf8','#d6caf4','#c8b8ef','#baa6ea','#ac95e4','#9e83de'],head:['#f3effc','#ebe5fa','#e3dcf8','#dbd2f5'],rule:['#c3b3ee','#f0b6d6'],line:'#8f78d6',pass:'#b3a0e8',fail:'#ece8f6',ink:'#4b3a7c'},
    {id:'peach',name:'🍑 هلویی',bars:['#fde1cc','#fcd3b6','#fbc5a0','#f9b78a','#f7a974','#f59b5f'],head:['#fff3ea','#feeadb','#fde1cc','#fcd8bd'],rule:['#f6c7a6','#f5b4c8'],line:'#e8935a',pass:'#f6b88c',fail:'#f3e7df',ink:'#7a4325'},
    {id:'mono',name:'⚫ ساده (مناسب چاپ سیاه‌وسفید)',bars:['#e5e7eb','#d1d5db','#bcc1c9','#a8aeb8','#949ba6','#808892'],head:['#f3f4f6','#eceef1','#e5e7eb','#dee1e6'],rule:['#9ca3af','#6b7280'],line:'#374151',pass:'#9ca3af',fail:'#eceef1',ink:'#111827'}
  ];
  function prTheme(){
    var e=document.getElementById('lbpr-theme');var id=e?e.value:'status';
    for(var i=0;i<PR_THEMES.length;i++){if(PR_THEMES[i].id===id)return PR_THEMES[i];}
    return PR_THEMES[0];
  }
  function prType(){var e=document.getElementById('lbpr-type');return e?e.value:'bar';}
  function prBodyFont(){var e=document.getElementById('lbpr-font');return pcFontCss(e?e.value:'');}
  function prHeadFont(){var e=document.getElementById('lbpr-head-font');return pcFontCss(e?e.value:'');}
  function lbprFontFamily(){return prBodyFont();}
  function lbprCurrentFontSize(){var s=parseInt(document.getElementById('lbpr-fontsize').value,10)||15;return Math.max(8,Math.min(30,s));}
  function prHex(c){return [parseInt(c.slice(1,3),16),parseInt(c.slice(3,5),16),parseInt(c.slice(5,7),16)];}
  function prMix(a,b,t){var x=prHex(a),y=prHex(b);return 'rgb('+Math.round(x[0]+(y[0]-x[0])*t)+','+Math.round(x[1]+(y[1]-x[1])*t)+','+Math.round(x[2]+(y[2]-x[2])*t)+')';}
  function lbprColorForPct(pct){
    if(pct<60)return{fill:'#f9c9c9',border:'#e26b6b'};      // قرمز ملایم - ضعیف
    if(pct<85)return{fill:'#bfdbfe',border:'#5b8def'};      // آبی ملایم - متوسط
    return{fill:'#b8ebcb',border:'#3fb677'};               // سبز ملایم - خوب
  }
  function prBarColor(i,pct,th){
    if(th.status)return lbprColorForPct(pct);
    var f=th.bars[i%th.bars.length];
    return{fill:f,border:prMix(f,'#1f2a44',.38)};
  }
  function prStatusKey(p){return p<60?'low':(p<85?'mid':'high');}
  function prApplyStyle(){
    var p=document.getElementById('lb-panel-passrate');
    if(!p)return;
    var th=prTheme();
    p.style.setProperty('--pr-font',prBodyFont());
    p.style.setProperty('--pr-head-font',prHeadFont());
    p.style.setProperty('--pr-size',lbprCurrentFontSize()+'px');
    for(var i=0;i<4;i++)p.style.setProperty('--pr-h'+(i+1),th.head[i]);
    p.style.setProperty('--pr-r1',th.rule[0]);
    p.style.setProperty('--pr-r2',th.rule[1]);
    p.style.setProperty('--pr-ink',th.ink);
    var lg=document.getElementById('lbpr-legend');
    if(lg)lg.style.display=th.status?'':'none';
  }
  (function(){
    var opts=PC_FONT_LIST.map(function(f){return '<option value="'+f[0]+'" style="font-family:'+PC_Q+f[0]+PC_Q+',Tahoma">'+f[1]+'</option>';}).join('');
    var a=document.getElementById('lbpr-font'),b=document.getElementById('lbpr-head-font');
    a.innerHTML=opts;b.innerHTML=opts;a.value='B Nazanin';b.value='B Nazanin';
    document.getElementById('lbpr-theme').innerHTML=PR_THEMES.map(function(t){return '<option value="'+t.id+'">'+t.name+'</option>';}).join('');
  })();
  var PR_REDRAW_TIMER=null;
  function prWaitFontsThenRedraw(){
    try{
      if(document.fonts&&document.fonts.load){
        var names=[document.getElementById('lbpr-font').value,document.getElementById('lbpr-head-font').value];
        Promise.all(names.map(function(n){return document.fonts.load('14px "'+n+'"');})).then(function(){lbprRecalc();}).catch(function(){});
      }
    }catch(e){}
  }
  function prStyleChanged(){
    prApplyStyle();
    lbprRecalc();
    prWaitFontsThenRedraw();
    lbSave('passrate-style',{font:document.getElementById('lbpr-font').value,head:document.getElementById('lbpr-head-font').value,size:lbprCurrentFontSize(),type:prType(),theme:prTheme().id},true);
  }
  ['lbpr-font','lbpr-head-font','lbpr-type','lbpr-theme'].forEach(function(id){document.getElementById(id).addEventListener('change',prStyleChanged);});
  function lbprApplyFontSize(px){
    px=Math.max(8,Math.min(30,parseInt(px,10)||15));
    document.getElementById('lbpr-fontsize').value=px;
    prApplyStyle();
    return px;
  }
  document.getElementById('lbpr-fontsize').addEventListener('input',function(){lbprApplyFontSize(this.value);prStyleChanged();});
  document.getElementById('btn-lbpr-fontsize-inc').onclick=function(){lbprApplyFontSize(lbprCurrentFontSize()+1);prStyleChanged();};
  document.getElementById('btn-lbpr-fontsize-dec').onclick=function(){lbprApplyFontSize(lbprCurrentFontSize()-1);prStyleChanged();};

  // ----- نمودارها (Canvas) — همه در مختصات محلی (0,0,w,h) رسم می‌شوند -----
  function prRoundTop(ctx,x,y,w,h,r){
    r=Math.max(0,Math.min(r,w/2,h));
    ctx.beginPath();
    ctx.moveTo(x,y+h);ctx.lineTo(x,y+r);ctx.quadraticCurveTo(x,y,x+r,y);
    ctx.lineTo(x+w-r,y);ctx.quadraticCurveTo(x+w,y,x+w,y+r);ctx.lineTo(x+w,y+h);ctx.closePath();
  }
  function prRoundRight(ctx,x,y,w,h,r){ // میله‌ی افقی: گرد از سمت چپ (سر میله)
    r=Math.max(0,Math.min(r,h/2,w));
    ctx.beginPath();
    ctx.moveTo(x+w,y);ctx.lineTo(x+r,y);ctx.quadraticCurveTo(x,y,x,y+r);
    ctx.lineTo(x,y+h-r);ctx.quadraticCurveTo(x,y+h,x+r,y+h);ctx.lineTo(x+w,y+h);ctx.closePath();
  }
  function prTitle(ctx,w,o){
    if(!o.title)return;
    ctx.fillStyle=o.th.ink;ctx.textAlign='center';ctx.font='bold 13px '+o.fh;
    ctx.fillText(o.title,w/2,16);
  }
  function prGrid(ctx,l,r,t,b,o,fmt,max,steps){
    ctx.strokeStyle='#e6ebf3';ctx.fillStyle='#8a97ab';ctx.lineWidth=1;ctx.textAlign='right';ctx.font='11px '+o.fb;
    for(var k=0;k<=steps;k++){
      var v=max*k/steps;
      var y=b-(b-t)*k/steps;
      ctx.beginPath();ctx.setLineDash(k===0?[]:[4,4]);ctx.moveTo(l,y);ctx.lineTo(r,y);ctx.stroke();
      ctx.fillText(fmt(v),l-6,y+4);
    }
    ctx.setLineDash([]);
  }
  function prChartBar(ctx,w,h,d,o){
    var padT=o.title?36:26,padB=34,padL=36,padR=12;
    var cw=w-padL-padR,ch=h-padT-padB,n=6,gap=o.small?9:16,bw=(cw-gap*(n-1))/n;
    prTitle(ctx,w,o);
    prGrid(ctx,padL,w-padR,padT,padT+ch,o,function(v){return toFaDigits(Math.round(v));},100,4);
    for(var i=0;i<n;i++){
      var pct=Math.max(0,Math.min(100,d.pct[i]));
      var bh=pct/100*ch,x=padL+(n-1-i)*(bw+gap),y=padT+ch-bh;
      var c=prBarColor(i,pct,o.th);
      if(bh>0){
        var g=ctx.createLinearGradient(0,y,0,y+bh);g.addColorStop(0,c.fill);g.addColorStop(1,prMix(c.fill,'#ffffff',.55));
        prRoundTop(ctx,x,y,bw,bh,8);ctx.fillStyle=g;ctx.fill();
        ctx.strokeStyle=c.border;ctx.lineWidth=1.6;ctx.stroke();
      }
      ctx.fillStyle='#1f2937';ctx.textAlign='center';ctx.font='bold '+(o.small?11:13)+'px '+o.fb;
      ctx.fillText(toFaDigits(pct)+'٪',x+bw/2,Math.max(padT-4,y-7));
      ctx.fillStyle='#4b5563';ctx.font=(o.small?11:12.5)+'px '+o.fh;
      ctx.fillText((o.small?'':'پایه ')+LBPR_GRADE_NAMES[i],x+bw/2,padT+ch+20);
    }
  }
  function prChartHBar(ctx,w,h,d,o){
    var padT=o.title?34:14,padB=26,padL=44,padR=62;
    var cw=w-padL-padR,ch=h-padT-padB,n=6,gap=o.small?7:11,bh=(ch-gap*(n-1))/n;
    prTitle(ctx,w,o);
    ctx.strokeStyle='#e6ebf3';ctx.fillStyle='#8a97ab';ctx.font='11px '+o.fb;ctx.textAlign='center';
    for(var k=0;k<=4;k++){
      var x=padL+cw-cw*k/4;
      ctx.beginPath();ctx.setLineDash(k===0?[]:[4,4]);ctx.moveTo(x,padT);ctx.lineTo(x,padT+ch);ctx.stroke();
      ctx.fillText(toFaDigits(k*25),x,padT+ch+16);
    }
    ctx.setLineDash([]);
    for(var i=0;i<n;i++){
      var pct=Math.max(0,Math.min(100,d.pct[i]));
      var len=pct/100*cw,y=padT+i*(bh+gap),xr=padL+cw,x0=xr-len;
      var c=prBarColor(i,pct,o.th);
      if(len>0){
        var g=ctx.createLinearGradient(x0,0,xr,0);g.addColorStop(0,c.fill);g.addColorStop(1,prMix(c.fill,'#ffffff',.55));
        prRoundRight(ctx,x0,y,len,bh,9);ctx.fillStyle=g;ctx.fill();ctx.strokeStyle=c.border;ctx.lineWidth=1.6;ctx.stroke();
      }
      ctx.fillStyle='#4b5563';ctx.textAlign='left';ctx.font=(o.small?11:12.5)+'px '+o.fh;
      ctx.fillText('پایه '+LBPR_GRADE_NAMES[i],xr+8,y+bh/2+4);
      ctx.fillStyle='#1f2937';ctx.textAlign='right';ctx.font='bold '+(o.small?11:13)+'px '+o.fb;
      ctx.fillText(toFaDigits(pct)+'٪',Math.min(x0-6,xr-6)<padL+30?x0+len-6:x0-6,y+bh/2+4);
    }
  }
  function prChartLine(ctx,w,h,d,o){
    var padT=o.title?38:28,padB=34,padL=36,padR=14;
    var cw=w-padL-padR,ch=h-padT-padB,n=6,step=cw/n;
    prTitle(ctx,w,o);
    prGrid(ctx,padL,w-padR,padT,padT+ch,o,function(v){return toFaDigits(Math.round(v));},100,4);
    var pts=[];
    for(var i=0;i<n;i++){pts.push({x:padL+(n-1-i)*step+step/2,y:padT+ch-Math.max(0,Math.min(100,d.pct[i]))/100*ch,p:d.pct[i]});}
    var ord=pts.slice().sort(function(a,b){return a.x-b.x;});
    var g=ctx.createLinearGradient(0,padT,0,padT+ch);g.addColorStop(0,prMix(o.th.line,'#ffffff',.55));g.addColorStop(1,'rgba(255,255,255,0)');
    ctx.beginPath();ctx.moveTo(ord[0].x,padT+ch);ord.forEach(function(p){ctx.lineTo(p.x,p.y);});ctx.lineTo(ord[n-1].x,padT+ch);ctx.closePath();ctx.fillStyle=g;ctx.globalAlpha=.75;ctx.fill();ctx.globalAlpha=1;
    ctx.beginPath();ord.forEach(function(p,k){if(k===0)ctx.moveTo(p.x,p.y);else ctx.lineTo(p.x,p.y);});
    ctx.strokeStyle=o.th.line;ctx.lineWidth=3;ctx.lineJoin='round';ctx.stroke();
    pts.forEach(function(p,i){
      var c=prBarColor(i,p.p,o.th);
      ctx.beginPath();ctx.arc(p.x,p.y,6,0,Math.PI*2);ctx.fillStyle='#fff';ctx.fill();ctx.lineWidth=3;ctx.strokeStyle=o.th.status?c.border:o.th.line;ctx.stroke();
      ctx.fillStyle='#1f2937';ctx.textAlign='center';ctx.font='bold '+(o.small?11:13)+'px '+o.fb;
      ctx.fillText(toFaDigits(p.p)+'٪',p.x,Math.max(padT-6,p.y-12));
      ctx.fillStyle='#4b5563';ctx.font=(o.small?11:12.5)+'px '+o.fh;
      ctx.fillText((o.small?'':'پایه ')+LBPR_GRADE_NAMES[i],p.x,padT+ch+20);
    });
  }
  function prChartGrouped(ctx,w,h,d,o){
    var padT=o.title?50:32,padB=34,padL=38,padR=12;
    var cw=w-padL-padR,ch=h-padT-padB,n=6,step=cw/n;
    var mx=1;for(var i=0;i<n;i++)mx=Math.max(mx,d.total[i],d.pass[i]);
    var nice=mx<=5?5:(mx<=10?10:Math.ceil(mx/10)*10);
    prTitle(ctx,w,o);
    prGrid(ctx,padL,w-padR,padT,padT+ch,o,function(v){return toFaDigits(Math.round(v));},nice,4);
    var bw=Math.min(o.small?16:26,step/2-4);
    var cT='#d5deec',cP=o.th.status?'#8fd9ac':o.th.pass;
    for(var j=0;j<n;j++){
      var cx=padL+(n-1-j)*step+step/2;
      [[d.total[j],cT,cx+2],[d.pass[j],cP,cx-bw-2]].forEach(function(b){
        var bh=b[0]/nice*ch,y=padT+ch-bh;
        if(bh>0){prRoundTop(ctx,b[2],y,bw,bh,6);ctx.fillStyle=b[1];ctx.fill();ctx.strokeStyle=prMix(b[1],'#1f2a44',.35);ctx.lineWidth=1.3;ctx.stroke();}
        ctx.fillStyle='#1f2937';ctx.textAlign='center';ctx.font='bold '+(o.small?10:12)+'px '+o.fb;
        ctx.fillText(toFaDigits(b[0]),b[2]+bw/2,Math.max(padT-3,y-5));
      });
      ctx.fillStyle='#4b5563';ctx.textAlign='center';ctx.font=(o.small?11:12.5)+'px '+o.fh;
      ctx.fillText((o.small?'':'پایه ')+LBPR_GRADE_NAMES[j],cx,padT+ch+20);
    }
    ctx.font=(o.small?10.5:12)+'px '+o.fh;ctx.textAlign='right';
    var lx=w-padR;
    ctx.fillStyle='#4b5563';ctx.fillText('تعداد کل',lx,padT-12);
    ctx.fillStyle=cT;ctx.fillRect(lx-ctx.measureText('تعداد کل').width-16,padT-21,11,11);
    var lx2=lx-ctx.measureText('تعداد کل').width-28;
    ctx.fillStyle='#4b5563';ctx.fillText('قبول',lx2,padT-12);
    ctx.fillStyle=cP;ctx.fillRect(lx2-ctx.measureText('قبول').width-16,padT-21,11,11);
  }
  function prChartDonut(ctx,w,h,d,o){
    var T=0,P=0;for(var i=0;i<6;i++){T+=d.total[i];P+=Math.min(d.pass[i],d.total[i]);}
    var pct=T>0?Math.round(P/T*100):0,fail=Math.max(0,T-P);
    prTitle(ctx,w,o);
    var top=o.title?26:6;
    var r=Math.min(w*0.3,(h-top-34)/2),cx=w/2+(o.small?0:-w*0.12),cy=top+(h-top)/2;
    var th=o.th,cP=th.status?'#8fd9ac':th.pass,cF=th.status?'#f6c1c1':th.fail;
    var a0=-Math.PI/2;
    ctx.lineWidth=r*0.3;ctx.lineCap='butt';
    ctx.beginPath();ctx.arc(cx,cy,r*0.85,0,Math.PI*2);ctx.strokeStyle=T>0?cF:'#eef2f8';ctx.stroke();
    if(T>0&&P>0){ctx.beginPath();ctx.arc(cx,cy,r*0.85,a0,a0+Math.PI*2*Math.min(1,P/T),false);ctx.strokeStyle=cP;ctx.stroke();}
    ctx.fillStyle=th.ink;ctx.textAlign='center';ctx.font='bold '+Math.round(r*0.4)+'px '+o.fh;
    ctx.fillText(T>0?toFaDigits(pct)+'٪':'—',cx,cy+r*0.08);
    ctx.fillStyle='#64748b';ctx.font=Math.round(Math.max(10,r*0.15))+'px '+o.fh;
    ctx.fillText('قبولی کل مدرسه',cx,cy+r*0.3);
    if(!o.small){
      var lx=w-14,ly=cy-22;
      ctx.textAlign='right';ctx.font='13px '+o.fh;
      [[cP,'قبول‌شده',P],[cF,'قبول‌نشده',fail],['#d5deec','کل دانش‌آموزان',T]].forEach(function(it,k){
        var y=ly+k*28;
        ctx.fillStyle=it[0];ctx.fillRect(lx-12,y-10,12,12);
        ctx.fillStyle='#374151';ctx.fillText(it[1]+': '+toFaDigits(it[2])+' نفر',lx-20,y);
      });
    }
  }
  function prChartRadar(ctx,w,h,d,o){
    prTitle(ctx,w,o);
    var top=o.title?24:0;
    var cx=w/2,cy=top+(h-top)/2+2,R=Math.min(w/2-(o.small?50:80),(h-top)/2-(o.small?44:50));
    function pt(i,v){var a=-Math.PI/2+i*Math.PI*2/6;return [cx+Math.cos(a)*R*v/100,cy+Math.sin(a)*R*v/100];}
    ctx.strokeStyle='#dfe6f1';ctx.lineWidth=1;
    [25,50,75,100].forEach(function(v){
      ctx.beginPath();for(var i=0;i<6;i++){var p=pt(i,v);if(i===0)ctx.moveTo(p[0],p[1]);else ctx.lineTo(p[0],p[1]);}ctx.closePath();ctx.stroke();
    });
    for(var i=0;i<6;i++){var e=pt(i,100);ctx.beginPath();ctx.moveTo(cx,cy);ctx.lineTo(e[0],e[1]);ctx.stroke();}
    ctx.beginPath();
    for(var j=0;j<6;j++){var q=pt(j,Math.max(0,Math.min(100,d.pct[j])));if(j===0)ctx.moveTo(q[0],q[1]);else ctx.lineTo(q[0],q[1]);}
    ctx.closePath();ctx.fillStyle=prMix(o.th.line,'#ffffff',.6);ctx.globalAlpha=.7;ctx.fill();ctx.globalAlpha=1;
    ctx.strokeStyle=o.th.line;ctx.lineWidth=2.6;ctx.lineJoin='round';ctx.stroke();
    for(var k=0;k<6;k++){
      var v=Math.max(0,Math.min(100,d.pct[k])),p2=pt(k,v),lp=pt(k,100);
      ctx.beginPath();ctx.arc(p2[0],p2[1],4.5,0,Math.PI*2);ctx.fillStyle='#fff';ctx.fill();ctx.lineWidth=2.4;ctx.strokeStyle=o.th.line;ctx.stroke();
      var a=-Math.PI/2+k*Math.PI*2/6,lx=cx+Math.cos(a)*(R+(o.small?16:22)),ly=cy+Math.sin(a)*(R+(o.small?14:18));
      ctx.textAlign=Math.abs(Math.cos(a))<0.2?'center':(Math.cos(a)>0?'left':'right');
      var up=Math.sin(a)<-0.5,ny=up?ly-14:ly,py=up?ly:ly+14;
      ctx.fillStyle='#4b5563';ctx.font=(o.small?11:12.5)+'px '+o.fh;ctx.fillText('پایه '+LBPR_GRADE_NAMES[k],lx,ny);
      ctx.fillStyle='#1f2937';ctx.font='bold '+(o.small?10.5:12)+'px '+o.fb;ctx.fillText(toFaDigits(d.pct[k])+'٪',lx,py);
    }
  }
  var PR_CHARTS={bar:prChartBar,hbar:prChartHBar,line:prChartLine,grouped:prChartGrouped,donut:prChartDonut,radar:prChartRadar};
  var PR_CHART_TITLES={bar:'میله‌ای عمودی',hbar:'میله‌ای افقی',line:'روند درصد قبولی',grouped:'مقایسه‌ی تعداد کل و قبول',donut:'قبولی کل مدرسه',radar:'نمودار راداری'};
  var LBPR_LAST={pct:[0,0,0,0,0,0],total:[0,0,0,0,0,0],pass:[0,0,0,0,0,0]};
  function lbprDrawChart(d){
    var canvas=document.getElementById('lbpr-chart');
    if(!canvas)return;
    var type=prType(),th=prTheme(),S=2,W=700,H=(type==='all')?820:340;
    canvas.width=W*S;canvas.height=H*S;
    canvas.style.width='100%';canvas.style.maxWidth=W+'px';canvas.style.height='auto';
    var ctx=canvas.getContext('2d');
    if(!ctx)return;
    ctx.setTransform(S,0,0,S,0,0);
    ctx.fillStyle='#ffffff';ctx.fillRect(0,0,W,H);
    var fb=prBodyFont(),fh=prHeadFont();
    function one(t,x,y,w,h,small,title){
      ctx.save();ctx.translate(x,y);ctx.beginPath();ctx.rect(0,0,w,h);ctx.clip();
      PR_CHARTS[t](ctx,w,h,d,{th:th,fb:fb,fh:fh,small:small,title:title});
      ctx.restore();
    }
    if(type==='all'){
      var order=['bar','hbar','line','grouped','donut','radar'],cw=W/2,chh=H/3;
      ctx.strokeStyle='#eef2f8';ctx.lineWidth=1;
      ctx.beginPath();ctx.moveTo(cw,10);ctx.lineTo(cw,H-10);ctx.moveTo(10,chh);ctx.lineTo(W-10,chh);ctx.moveTo(10,chh*2);ctx.lineTo(W-10,chh*2);ctx.stroke();
      order.forEach(function(t,i){one(t,(1-(i%2))*cw+6,Math.floor(i/2)*chh+4,cw-12,chh-8,true,PR_CHART_TITLES[t]);});
    }else{
      one(type,0,0,W,H,false,'');
    }
  }
  function prUpdateKpis(d){
    var T=0,P=0,best=-1,low=101,bi=-1,li=-1;
    for(var i=0;i<6;i++){
      T+=d.total[i];P+=Math.min(d.pass[i],d.total[i]);
      if(d.total[i]>0){
        if(d.pct[i]>best){best=d.pct[i];bi=i;}
        if(d.pct[i]<low){low=d.pct[i];li=i;}
      }
    }
    function set(id,v){var e=document.getElementById(id);if(e)e.textContent=v;}
    set('lbpr-kpi-avg',T>0?toFaDigits(Math.round(P/T*100))+'٪':'—');
    set('lbpr-kpi-best',bi>=0?'پایه '+LBPR_GRADE_NAMES[bi]+' ('+toFaDigits(best)+'٪)':'—');
    set('lbpr-kpi-low',li>=0?'پایه '+LBPR_GRADE_NAMES[li]+' ('+toFaDigits(low)+'٪)':'—');
    set('lbpr-kpi-count',T>0?toFaDigits(P)+' از '+toFaDigits(T):'—');
  }
  function lbprRecalc(){
    var d={pct:[],total:[],pass:[]};
    for(var g=1;g<=6;g++){
      var totalInp=document.querySelector('.lbpr-total[data-grade="'+g+'"]');
      var passInp=document.querySelector('.lbpr-pass[data-grade="'+g+'"]');
      var pctCell=document.querySelector('.lbpr-pct[data-grade="'+g+'"]');
      var t=parseInt(toEnDigits(totalInp.value),10)||0;
      var p=parseInt(toEnDigits(passInp.value),10)||0;
      var pct=t>0?Math.min(100,Math.round((p/t)*100)):0;
      pctCell.textContent=toFaDigits(pct)+'٪';
      pctCell.className='lbpr-pct'+(t>0?' pr-'+prStatusKey(pct):'');
      d.pct.push(pct);d.total.push(t);d.pass.push(p);
    }
    LBPR_LAST=d;
    lbprDrawChart(d);
    prUpdateKpis(d);
    return d.pct;
  }
  document.getElementById('lbpr-table').addEventListener('input',function(e){
    if(e.target&&(e.target.classList.contains('lbpr-total')||e.target.classList.contains('lbpr-pass'))){
      var cleaned=toEnDigits(e.target.value).replace(/[^0-9]/g,'').slice(0,3);
      e.target.value=toFaDigits(cleaned);
      lbprRecalc();
    }
  });
  var LB_PASSRATE_LOADED=false;
  async function lbLoadPassrateIfNeeded(){
    if(LB_PASSRATE_LOADED){prApplyStyle();lbprRecalc();return;}
    LB_PASSRATE_LOADED=true;
    var st=await lbLoad('passrate-style');
    if(st){
      if(st.font&&pcFontOk(st.font))document.getElementById('lbpr-font').value=st.font;
      if(st.head&&pcFontOk(st.head))document.getElementById('lbpr-head-font').value=st.head;
      if(st.size)document.getElementById('lbpr-fontsize').value=st.size;
      if(st.type&&document.querySelector('#lbpr-type option[value="'+st.type+'"]'))document.getElementById('lbpr-type').value=st.type;
      if(st.theme&&document.querySelector('#lbpr-theme option[value="'+st.theme+'"]'))document.getElementById('lbpr-theme').value=st.theme;
    }
    var saved=await lbLoad('passrate');
    if(saved){
      document.getElementById('lbpr-school').value=saved.school||'';
      document.getElementById('lbpr-year').value=saved.year||'';
      if(!st){
        var pf=saved.font;
        if(pf&&LBPR_LEGACY_FONT.hasOwnProperty(pf))pf=LBPR_LEGACY_FONT[pf];
        if(pf&&pcFontOk(pf)){document.getElementById('lbpr-font').value=pf;document.getElementById('lbpr-head-font').value=pf;}
        if(saved.fontSize)document.getElementById('lbpr-fontsize').value=saved.fontSize;
      }
      if(saved.grades){
        saved.grades.forEach(function(row,idx){
          var g=idx+1;
          var totalInp=document.querySelector('.lbpr-total[data-grade="'+g+'"]');
          var passInp=document.querySelector('.lbpr-pass[data-grade="'+g+'"]');
          if(totalInp)totalInp.value=toFaDigits(toEnDigits(row.total||''));
          if(passInp)passInp.value=toFaDigits(toEnDigits(row.pass||''));
        });
      }
    }
    prApplyStyle();
    lbprRecalc();
    prWaitFontsThenRedraw();
  }
  document.getElementById('btn-lbpr-save').onclick=function(){
    var grades=[];
    for(var g=1;g<=6;g++){
      var totalInp=document.querySelector('.lbpr-total[data-grade="'+g+'"]');
      var passInp=document.querySelector('.lbpr-pass[data-grade="'+g+'"]');
      grades.push({total:totalInp.value,pass:passInp.value});
    }
    lbSave('passrate-style',{font:document.getElementById('lbpr-font').value,head:document.getElementById('lbpr-head-font').value,size:lbprCurrentFontSize(),type:prType(),theme:prTheme().id},true);
    lbSave('passrate',{school:document.getElementById('lbpr-school').value,year:document.getElementById('lbpr-year').value,font:document.getElementById('lbpr-font').value,fontSize:lbprCurrentFontSize(),grades:grades});
    toast('ذخیره شد ✅');
  };
  var PR_STATUS_CHIP={low:['#fff1f1','#b91c1c'],mid:['#eef5ff','#1d4ed8'],high:['#eefbf3','#15803d']};
  function lbprExportHtml(){
    var school=document.getElementById('lbpr-school').value||'.......................';
    var year=document.getElementById('lbpr-year').value||'.......................';
    var pcts=lbprRecalc();
    var d=LBPR_LAST,th=prTheme();
    var canvas=document.getElementById('lbpr-chart');
    var imgData=canvas.toDataURL('image/png');
    var line='#c5d3e8';
    var base='border:1px solid '+line+';padding:9px 10px;text-align:center;vertical-align:middle;';
    var hf=prHeadFont();
    var h='<p style="text-align:center;font-weight:bold;font-size:1.3em;line-height:2;color:'+th.ink+';font-family:'+hf+'">نمودار درصد قبولی دانش‌آموزان مدرسه '+esc(school)+' - سال تحصیلی '+esc(year)+'</p>';
    h+='<div style="width:96px;margin:0 auto 14px;border-bottom:4px solid '+th.rule[0]+';height:2px;font-size:1px;line-height:1px">&nbsp;</div>';
    h+='<table style="width:100%;border-collapse:collapse;border:1px solid '+line+'"><thead><tr>';
    ['پایه','تعداد کل دانش‌آموزان','تعداد قبول','درصد قبولی'].forEach(function(t,i){
      h+='<th style="'+base+'background:'+th.head[i]+';color:'+th.ink+';font-weight:bold;font-family:'+hf+'">'+t+'</th>';
    });
    h+='</tr></thead><tbody>';
    LBPR_GRADE_NAMES.forEach(function(name,idx){
      var g=idx+1;
      var t=document.querySelector('.lbpr-total[data-grade="'+g+'"]').value||'۰';
      var p=document.querySelector('.lbpr-pass[data-grade="'+g+'"]').value||'۰';
      var chip=d.total[idx]>0?PR_STATUS_CHIP[prStatusKey(pcts[idx])]:['#ffffff','#374151'];
      h+='<tr><td style="'+base+'background:#f8f6fd;font-weight:bold;color:#4b3a7c;font-family:'+hf+'">'+esc(name)+'</td><td style="'+base+'">'+esc(t)+'</td><td style="'+base+'">'+esc(p)+'</td><td style="'+base+'background:'+chip[0]+';color:'+chip[1]+';font-weight:bold">'+toFaDigits(pcts[idx])+'٪</td></tr>';
    });
    h+='</tbody></table>';
    function txt(id){var e=document.getElementById(id);return e?esc(e.textContent):'';}
    h+='<table style="width:100%;border-collapse:separate;border-spacing:8px;margin-top:8px"><tr>'
      +'<td style="width:25%;text-align:center;padding:10px 4px;background:#f1f5fd;border:1px solid #d3e0f5;border-top:4px solid #9fc0f0">میانگین قبولی مدرسه<br><b style="font-size:1.3em;color:'+th.ink+'">'+txt('lbpr-kpi-avg')+'</b></td>'
      +'<td style="width:25%;text-align:center;padding:10px 4px;background:#effaf3;border:1px solid #cfeedb;border-top:4px solid #8fd9ac">بهترین پایه<br><b style="font-size:1.3em;color:'+th.ink+'">'+txt('lbpr-kpi-best')+'</b></td>'
      +'<td style="width:25%;text-align:center;padding:10px 4px;background:#fff4f4;border:1px solid #f6d5d5;border-top:4px solid #f0a6a6">نیازمند توجه بیشتر<br><b style="font-size:1.3em;color:'+th.ink+'">'+txt('lbpr-kpi-low')+'</b></td>'
      +'<td style="width:25%;text-align:center;padding:10px 4px;background:#f6f3fd;border:1px solid #dcd3f3;border-top:4px solid #b3a2e6">قبول‌شدگان از کل<br><b style="font-size:1.3em;color:'+th.ink+'">'+txt('lbpr-kpi-count')+'</b></td>'
      +'</tr></table>';
    h+='<div style="text-align:center;margin-top:10px"><img src="'+imgData+'" style="max-width:100%;width:640px"></div>';
    if(th.status)h+='<p style="margin-top:10px;font-size:0.85em;color:#64748b">رنگ‌بندی: قرمز ملایم = زیر ۶۰٪ | آبی ملایم = ۶۰ تا ۸۴٪ | سبز ملایم = ۸۵٪ به بالا</p>';
    return h;
  }
  function lbprWord(landscape,fontSize){
    lbWordExport('',lbprExportHtml(),'درصد-قبولی-دانش-آموزان',landscape,prBodyFont(),fontSize);
  }
  function lbprPrint(landscape,fontSize){
    var title='نمودار درصد قبولی دانش‌آموزان';
    var body=lbprExportHtml();
    var w=window.open('','_blank');
    if(!w){toast('اجازه‌ی باز کردن پنجره‌ی چاپ داده نشد (popup blocked)');return;}
    var css='<style>'+lpFaceCss()+'@page{size:A4 '+(landscape?'landscape':'portrait')+';margin:10mm}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}'
      +'body{direction:rtl;margin:0;padding:6px;font-family:'+prBodyFont()+';font-size:'+fontSize+'px;color:#1f2937}table,td,th{font-size:inherit}</style>';
    w.document.write('<!DOCTYPE html><html dir="rtl"><head><meta charset="utf-8"><title>'+esc(title)+'</title>'+css+'</head><body>'+body+'</body></html>');
    w.document.close();
    printExportWindow(w);
  }
