  // ===================== ۵. صورتجلسه شورای آموزشی اولیا =====================
  var LB_COUNCIL_HEADERS=['ردیف','نام و نام خانوادگی','سمت / نقش','امضاء'];
  document.getElementById('btn-lbc-build').onclick=function(){
    var n=parseInt(document.getElementById('lbc-rows').value,10)||10;
    lbRebuildPreserving('lbc-table',LB_COUNCIL_HEADERS,n);
  };
  document.getElementById('btn-lbc-addrow').onclick=function(){lbAddSimpleRow('lbc-table',LB_COUNCIL_HEADERS.length);};
  document.getElementById('btn-lbc-build').click();

  // ----- فونت، اندازه و تم -----
  function lbcFontVal(){return document.getElementById('lbc-font').value||'B Nazanin';}
  function lbcHeadVal(){return document.getElementById('lbc-head-font').value||'B Nazanin';}
  function lbcThemeVal(){return document.getElementById('lbc-theme').value||'blue';}
  function lbcSizeVal(){var s=parseInt(document.getElementById('lbc-fontsize').value,10)||14;return Math.max(8,Math.min(30,s));}
  function lbcFontFamily(){return RCC.fontCss(lbcFontVal());}
  function lbcApplyStyle(){
    var p=document.getElementById('lb-panel-council');
    if(!p)return;
    var T=RCC.theme(lbcThemeVal());
    p.style.setProperty('--lc-font',RCC.fontCss(lbcFontVal()));
    p.style.setProperty('--lc-head-font',RCC.fontCss(lbcHeadVal()));
    p.style.setProperty('--lc-size',lbcSizeVal()+'px');
    p.style.setProperty('--lc-a',T.a);p.style.setProperty('--lc-ink',T.ink);p.style.setProperty('--lc-line',T.line);
    p.style.setProperty('--lc-tint',T.tint);p.style.setProperty('--lc-b1',T.band[0]);p.style.setProperty('--lc-b2',T.band[1]);
  }
  (function(){
    var opts=PC_FONT_LIST.map(function(f){return '<option value="'+f[0]+'" style="font-family:'+PC_Q+f[0]+PC_Q+',Tahoma">'+f[1]+'</option>';}).join('');
    var a=document.getElementById('lbc-font'),b=document.getElementById('lbc-head-font');
    a.innerHTML=opts;b.innerHTML=opts;a.value='B Nazanin';b.value='B Nazanin';
    document.getElementById('lbc-theme').innerHTML=RCC.THEMES.map(function(t){return '<option value="'+t.id+'">'+t.name+'</option>';}).join('');
  })();
  function lbcStyleChanged(){
    lbcApplyStyle();
    setTimeout(lbcGrowAll,30);
    lbSave('council-style',{font:lbcFontVal(),head:lbcHeadVal(),theme:lbcThemeVal(),size:lbcSizeVal()},true);
  }
  ['lbc-font','lbc-head-font','lbc-theme'].forEach(function(id){document.getElementById(id).addEventListener('change',lbcStyleChanged);});
  document.getElementById('lbc-fontsize').addEventListener('input',lbcStyleChanged);
  document.getElementById('btn-lbc-fontsize-inc').onclick=function(){document.getElementById('lbc-fontsize').value=Math.min(30,lbcSizeVal()+1);lbcStyleChanged();};
  document.getElementById('btn-lbc-fontsize-dec').onclick=function(){document.getElementById('lbc-fontsize').value=Math.max(8,lbcSizeVal()-1);lbcStyleChanged();};

  // ----- بخش‌های دلخواه (هر بخش: عنوان قابل ویرایش + چند «مورد»)، پیش‌فرض: خلاصه مباحث و تصمیمات -----
  var LBC_SECTIONS=[];
  var LBC_NEXT=1;
  function lbcNewSection(title,items){return {id:'s'+(LBC_NEXT++),title:title,items:(items&&items.length)?items.slice():['','']};}
  function lbcDefaultSections(){return [lbcNewSection('خلاصه مباحث مطرح شده'),lbcNewSection('تصمیمات و پیشنهادهای ارائه‌شده')];}
  function lbcGrow(ta){ta.style.height='auto';ta.style.height=Math.max(46,ta.scrollHeight+2)+'px';}
  function lbcGrowAll(){document.querySelectorAll('#lbc-sections .lbc-item-text').forEach(lbcGrow);}
  function lbcUpdateNumbers(){
    document.querySelectorAll('#lbc-sections .lbc-sec').forEach(function(el,i){
      var no=el.querySelector('.lbc-sec-no');if(no)no.textContent=toFaDigits(i+1);
    });
    var lab=document.getElementById('lbc-rows-label');
    if(lab)lab.textContent=toFaDigits(LBC_SECTIONS.length+1)+'- تعداد اعضای جلسه: ';
  }
  function lbcRender(focusSecId,focusItemIdx){
    var box=document.getElementById('lbc-sections');
    var h='';
    LBC_SECTIONS.forEach(function(sec,si){
      h+='<div class="lbc-sec" data-id="'+sec.id+'"><div class="lbc-sec-head"><span class="lbc-sec-no">'+toFaDigits(si+1)+'</span>'
        +'<input type="text" class="lbc-sec-title" value="'+esc(sec.title)+'" placeholder="عنوان بخش">'
        +'<button type="button" class="btn sm sec lbc-add-item">➕ مورد جدید</button>'
        +'<button type="button" class="btn sm danger lbc-del-sec" title="حذف این بخش">🗑️</button></div><div class="lbc-items">';
      sec.items.forEach(function(t,ii){
        h+='<div class="lbc-item"><span class="lbc-item-no">'+toFaDigits(ii+1)+'</span>'
          +'<textarea class="lbc-item-text" rows="2" data-i="'+ii+'" placeholder="متن را بنویسید...">'+esc(t)+'</textarea>'
          +'<button type="button" class="lbc-item-del" data-i="'+ii+'" title="حذف این مورد">✕</button></div>';
      });
      h+='</div></div>';
    });
    box.innerHTML=h;
    box.querySelectorAll('.lbc-sec').forEach(function(el){
      var sec=LBC_SECTIONS.find(function(s){return s.id===el.dataset.id;});
      el.querySelector('.lbc-sec-title').addEventListener('input',function(){sec.title=this.value;});
      el.querySelectorAll('.lbc-item-text').forEach(function(ta){
        ta.addEventListener('input',function(){sec.items[parseInt(ta.dataset.i,10)]=ta.value;lbcGrow(ta);});
      });
      el.querySelectorAll('.lbc-item-del').forEach(function(btn){
        btn.addEventListener('click',function(){
          var i=parseInt(btn.dataset.i,10);
          if(sec.items.length<=1)sec.items[0]='';else sec.items.splice(i,1);
          lbcRender();
        });
      });
      el.querySelector('.lbc-add-item').addEventListener('click',function(){
        sec.items.push('');
        lbcRender(sec.id,sec.items.length-1);
      });
      el.querySelector('.lbc-del-sec').addEventListener('click',function(){
        if(!confirm('این بخش با همه‌ی موردهایش حذف شود؟'))return;
        LBC_SECTIONS=LBC_SECTIONS.filter(function(s){return s.id!==sec.id;});
        lbcRender();
      });
    });
    lbcUpdateNumbers();
    setTimeout(lbcGrowAll,0);
    if(focusSecId){
      var secEl=box.querySelector('.lbc-sec[data-id="'+focusSecId+'"]');
      var ta=secEl&&secEl.querySelectorAll('.lbc-item-text')[focusItemIdx];
      if(ta)ta.focus();
    }
  }
  document.getElementById('btn-lbc-add-section').onclick=function(){
    var sec=lbcNewSection('بخش جدید');
    LBC_SECTIONS.push(sec);
    lbcRender();
    var el=document.querySelector('#lbc-sections .lbc-sec[data-id="'+sec.id+'"] .lbc-sec-title');
    if(el){el.focus();el.select();}
  };
  LBC_SECTIONS=lbcDefaultSections();
  lbcRender();

  // ----- خروجی Word / چاپ (پیش‌فرض افقی؛ در حالت افقی بخش‌ها دو‌ستونه کنار هم قرار می‌گیرند) -----
  function lbcSectionTable(sec,idx,T,fh){
    var line=T.line;
    var cell='border:1px solid '+line+';padding:7px 9px;vertical-align:top;line-height:1.8;';
    var h='<table style="width:100%;border-collapse:collapse;table-layout:fixed;border:1px solid '+line+'"><colgroup><col style="width:8%"><col style="width:92%"></colgroup>';
    h+='<tr><td colspan="2" style="'+cell+'background:'+T.a+';color:'+T.ink+';font-weight:bold;font-family:'+fh+';font-size:1.1em">'+toFaDigits(idx+1)+'- '+esc(sec.title||'')+'</td></tr>';
    var items=(sec.items&&sec.items.length)?sec.items:[''];
    items.forEach(function(t,i){
      var txt=String(t||'');
      var body=txt.trim()?esc(txt).split(String.fromCharCode(13)).join('').split(String.fromCharCode(10)).join('<br>'):'&nbsp;';
      var pad=txt.trim()?'':'padding:11px 9px;';
      h+='<tr style="page-break-inside:avoid"><td style="'+cell+'text-align:center;font-weight:bold;color:'+T.ink+';background:'+T.tint+'">'+toFaDigits(i+1)+'</td><td style="'+cell+pad+'text-align:right">'+body+'</td></tr>';
    });
    h+='</table>';
    return h;
  }
  function lbCouncilExportHtml(landscape){
    if(landscape===undefined)landscape=true;
    var T=RCC.theme(lbcThemeVal()),fh=RCC.fontCss(lbcHeadVal()),line=T.line;
    var lab='border:1px solid '+line+';padding:7px 8px;background:'+T.a+';color:'+T.ink+';font-weight:bold;text-align:center;font-family:'+fh+';';
    var val='border:1px solid '+line+';padding:7px 8px;text-align:right;';
    function v(id){var e=document.getElementById(id);var s=e?e.value:'';return s&&s.trim()?esc(s):'&nbsp;';}
    var h='<div style="height:7px;background:'+T.band[0]+';background:linear-gradient(90deg,'+T.band[0]+','+T.band[1]+');border-radius:6px;margin-bottom:10px;font-size:1px;line-height:1px">&nbsp;</div>';
    h+='<p style="text-align:center;font-weight:bold;font-size:1.6em;margin:0 0 4px;color:'+T.ink+';font-family:'+fh+'">جدول شماره ۱: جلسات شورای آموزشی اولیا</p>';
    h+='<div style="width:110px;margin:0 auto 12px;border-bottom:4px solid '+T.band[0]+';height:2px;font-size:1px;line-height:1px">&nbsp;</div>';
    h+='<table style="width:100%;border-collapse:collapse;table-layout:fixed;margin-bottom:12px"><colgroup>'+'<col style="width:11%"><col style="width:14%">'.repeat(4)+'</colgroup><tr>'
      +'<td style="'+lab+'">تاریخ برگزاری</td><td style="'+val+'">'+v('lbc-date')+'</td>'
      +'<td style="'+lab+'">موضوع جلسه</td><td style="'+val+'">'+v('lbc-topic')+'</td>'
      +'<td style="'+lab+'">شماره جلسه</td><td style="'+val+'">'+v('lbc-num')+'</td>'
      +'<td style="'+lab+'">ساعت تشکیل</td><td style="'+val+'">'+v('lbc-time')+'</td></tr></table>';
    var tables=LBC_SECTIONS.map(function(sec,i){return lbcSectionTable(sec,i,T,fh);});
    if(landscape&&tables.length>1){
      h+='<table style="width:100%;border-collapse:collapse;table-layout:fixed"><colgroup><col style="width:49%"><col style="width:2%"><col style="width:49%"></colgroup>';
      for(var i=0;i<tables.length;i+=2){
        h+='<tr><td style="border:none;padding:0 0 10px 0;vertical-align:top">'+tables[i]+'</td><td style="border:none;padding:0">&nbsp;</td><td style="border:none;padding:0 0 10px 0;vertical-align:top">'+(tables[i+1]||'')+'</td></tr>';
      }
      h+='</table>';
    }else{
      tables.forEach(function(t){h+='<div style="margin-bottom:10px">'+t+'</div>';});
    }
    var rows=lbTableToRows(document.getElementById('lbc-table'));
    var cell='border:1px solid '+line+';padding:9px 8px;vertical-align:middle;line-height:1.6;';
    h+='<table style="width:100%;border-collapse:collapse;table-layout:fixed;border:1px solid '+line+';margin-top:4px"><colgroup><col style="width:7%"><col style="width:38%"><col style="width:30%"><col style="width:25%"></colgroup>';
    h+='<tr><td colspan="4" style="'+cell+'background:'+T.a+';color:'+T.ink+';font-weight:bold;font-family:'+fh+';font-size:1.1em">'+toFaDigits(LBC_SECTIONS.length+1)+'- اسامی اعضای جلسه</td></tr><tr>';
    LB_COUNCIL_HEADERS.forEach(function(hd){h+='<td style="'+cell+'background:'+T.tint+';color:'+T.ink+';font-weight:bold;text-align:center;font-family:'+fh+'">'+esc(hd)+'</td>';});
    h+='</tr>';
    for(var r=1;r<rows.length;r++){
      h+='<tr style="page-break-inside:avoid">';
      LB_COUNCIL_HEADERS.forEach(function(hd,c){
        var x=rows[r][c]==null?'':rows[r][c];
        if(c===0)h+='<td style="'+cell+'text-align:center;font-weight:bold;color:'+T.ink+';background:'+T.tint+'">'+toFaDigits(x)+'</td>';
        else h+='<td style="'+cell+'text-align:right">'+(x===''?'&nbsp;':esc(x))+'</td>';
      });
      h+='</tr>';
    }
    h+='</table>';
    h+='<table style="width:100%;border-collapse:collapse;table-layout:fixed;margin-top:14px"><tr><td style="border:none;width:62%">&nbsp;</td><td style="border:1px solid '+line+';padding:8px;height:70px;vertical-align:top;text-align:center;font-weight:bold;color:'+T.ink+';background:'+T.tint+'">امضاء و تأیید مدیر مدرسه</td></tr></table>';
    return h;
  }
  function lbcWord(landscape,size){
    lbWordExport('',lbCouncilExportHtml(landscape),'صورتجلسه-شورای-آموزشی',landscape,lbcFontFamily(),size);
  }
  function lbcPrint(landscape,size){
    var body=lbCouncilExportHtml(landscape);
    var w=window.open('','_blank');
    if(!w){toast('اجازه‌ی باز کردن پنجره‌ی چاپ داده نشد (popup blocked)');return;}
    var css='<style>'+RCC.faceCss(location.origin)+'@page{size:A4 '+(landscape?'landscape':'portrait')+';margin:8mm}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}'
      +'body{direction:rtl;margin:0;padding:4px;font-family:'+lbcFontFamily()+';font-size:'+size+'px;color:#1f2937}table,td,th{font-size:inherit;word-break:break-word}</style>';
    w.document.write('<!DOCTYPE html><html dir="rtl"><head><meta charset="utf-8"><title>جلسات شورای آموزشی اولیا</title>'+css+'</head><body>'+body+'</body></html>');
    w.document.close();
    printExportWindow(w);
  }
  document.getElementById('btn-lb-council-word').onclick=function(){lbcWord(true,lbcSizeVal()-2);};
  document.getElementById('btn-lb-council-pdf').onclick=function(){lbcPrint(true,lbcSizeVal()-2);};
  document.getElementById('btn-lbc-print-opts-toggle').onclick=function(){
    var drawer=document.getElementById('lbc-print-opts-drawer');
    if(drawer.classList.contains('hidden'))document.getElementById('lbc-print-fontsize').value=Math.max(6,lbcSizeVal()-2);
    drawer.classList.toggle('hidden');
  };
  document.getElementById('btn-lbc-print-custom').onclick=function(){
    lbcPrint(document.getElementById('lbc-print-orientation').value==='landscape',parseInt(document.getElementById('lbc-print-fontsize').value,10)||12);
  };
  document.getElementById('btn-lbc-word-custom').onclick=function(){
    lbcWord(document.getElementById('lbc-print-orientation').value==='landscape',parseInt(document.getElementById('lbc-print-fontsize').value,10)||12);
  };
  document.getElementById('btn-lb-council-excel').onclick=function(){
    lbExcelExport('صورتجلسه-شورای-آموزشی',function(wb){
      var ws=wb.addWorksheet('صورتجلسه',{views:[{rightToLeft:true}]});
      ws.addRow(['تاریخ برگزاری',document.getElementById('lbc-date').value]);
      ws.addRow(['موضوع جلسه',document.getElementById('lbc-topic').value]);
      ws.addRow(['شماره جلسه',document.getElementById('lbc-num').value]);
      ws.addRow(['ساعت تشکیل',document.getElementById('lbc-time').value]);
      ws.addRow([]);
      LBC_SECTIONS.forEach(function(sec,i){
        ws.addRow([(i+1)+'- '+(sec.title||'')]);
        (sec.items||[]).forEach(function(t,j){ws.addRow([(j+1),t]);});
        ws.addRow([]);
      });
      lbTableToRows(document.getElementById('lbc-table')).forEach(function(r){ws.addRow(r);});
      ws.columns.forEach(function(c){c.width=28;});
    });
  };
  var LB_COUNCIL_LOADED=false;
  async function lbLoadCouncilIfNeeded(){
    if(LB_COUNCIL_LOADED){lbcApplyStyle();setTimeout(lbcGrowAll,60);return;}
    LB_COUNCIL_LOADED=true;
    var st=await lbLoad('council-style');
    if(st){
      if(st.font)document.getElementById('lbc-font').value=RCC.fontName(st.font);
      if(st.head)document.getElementById('lbc-head-font').value=RCC.fontName(st.head);
      if(st.theme)document.getElementById('lbc-theme').value=RCC.theme(st.theme).id;
      if(st.size)document.getElementById('lbc-fontsize').value=st.size;
    }
    lbcApplyStyle();
    var saved=await lbLoad('council');
    if(saved){
      if(saved.meta){
        document.getElementById('lbc-date').value=saved.meta.date||'';
        document.getElementById('lbc-topic').value=saved.meta.topic||'';
        document.getElementById('lbc-num').value=saved.meta.num||'';
        document.getElementById('lbc-time').value=saved.meta.time||'';
      }
      if(saved.sections&&saved.sections.length){
        LBC_SECTIONS=saved.sections.map(function(s){return lbcNewSection(String(s.title||''),(s.items||[]).map(String));});
      }else if(saved.summary||saved.decisions){
        // ذخیره‌های قدیمی: هر کدام یک «مورد» شد
        LBC_SECTIONS=[lbcNewSection('خلاصه مباحث مطرح شده',[String(saved.summary||'')]),lbcNewSection('تصمیمات و پیشنهادهای ارائه‌شده',[String(saved.decisions||'')])];
      }
      lbcRender();
      if(saved.rowCount){document.getElementById('lbc-rows').value=saved.rowCount;document.getElementById('btn-lbc-build').click();}
      if(saved.rows)lbFillTableRows('lbc-table',saved.rows);
    }
    setTimeout(lbcGrowAll,60);
  }
  document.getElementById('btn-lbc-save').onclick=function(){
    lbSave('council-style',{font:lbcFontVal(),head:lbcHeadVal(),theme:lbcThemeVal(),size:lbcSizeVal()},true);
    lbSave('council',{
      meta:{date:document.getElementById('lbc-date').value,topic:document.getElementById('lbc-topic').value,num:document.getElementById('lbc-num').value,time:document.getElementById('lbc-time').value},
      sections:LBC_SECTIONS.map(function(s){return {title:s.title,items:s.items.slice()};}),
      rowCount:parseInt(document.getElementById('lbc-rows').value,10)||10,
      rows:lbTableToRows(document.getElementById('lbc-table')).slice(1)
    });
  };

  // ===================== ۶. جلسات فردی با اولیا =====================
  var LB_MEET_HEADERS=['ردیف','نام و نام خانوادگی ولی','نسبت با دانش‌آموز','تاریخ دیدار','موضوع دیدار','نتایج (تصمیمات، راهکارها، پیگیری)'];
  document.getElementById('btn-lbm-build').onclick=function(){
    var n=parseInt(document.getElementById('lbm-rows').value,10)||15;
    lbRebuildPreserving('lbm-table',LB_MEET_HEADERS,n);
  };
  document.getElementById('btn-lbm-addrow').onclick=function(){lbAddSimpleRow('lbm-table',LB_MEET_HEADERS.length);};
  document.getElementById('btn-lbm-build').click();
  function lbMeetingsExportHtml(){
    var meta=lbMetaBlock([['نام مدرسه','lbm-school'],['نام آموزگار','lbm-teacher'],['پایه تحصیلی','lbm-grade'],['سال تحصیلی','lbm-year']]);
    var rows=lbTableToRows(document.getElementById('lbm-table'));
    return meta+lbRowsToHtmlTable(rows)+'<p style="margin-top:14px"><b>ادامه جلسات فردی با اولیا</b></p>';
  }
  document.getElementById('btn-lb-meetings-word').onclick=function(){lbWordExport('جدول ۱۰ - جلسات فردی با اولیا',lbMeetingsExportHtml(),'جلسات-فردی-با-اولیا',true);};
  document.getElementById('btn-lb-meetings-pdf').onclick=function(){lbPrintExport('جدول ۱۰ - جلسات فردی با اولیا',lbMeetingsExportHtml(),true);};
  document.getElementById('btn-lb-meetings-excel').onclick=function(){
    lbExcelExport('جلسات-فردی-با-اولیا',function(wb){
      lbAddExcelSheet(wb,'جلسات فردی',lbTableToRows(document.getElementById('lbm-table')));
    });
  };
  var LB_MEETINGS_LOADED=false;
  async function lbLoadMeetingsIfNeeded(){
    if(LB_MEETINGS_LOADED)return;
    LB_MEETINGS_LOADED=true;
    var saved=await lbLoad('meetings');
    if(!saved)return;
    if(saved.meta){
      document.getElementById('lbm-school').value=saved.meta.school||'';
      document.getElementById('lbm-teacher').value=saved.meta.teacher||'';
      document.getElementById('lbm-grade').value=saved.meta.grade||'';
      document.getElementById('lbm-year').value=saved.meta.year||'';
    }
    if(saved.rowCount){document.getElementById('lbm-rows').value=saved.rowCount;document.getElementById('btn-lbm-build').click();}
    if(saved.rows)lbFillTableRows('lbm-table',saved.rows);
  }
  document.getElementById('btn-lbm-save').onclick=function(){
    lbSave('meetings',{
      meta:{school:document.getElementById('lbm-school').value,teacher:document.getElementById('lbm-teacher').value,grade:document.getElementById('lbm-grade').value,year:document.getElementById('lbm-year').value},
      rowCount:parseInt(document.getElementById('lbm-rows').value,10)||15,
      rows:lbTableToRows(document.getElementById('lbm-table')).slice(1)
    });
  };

  // ===== ستون و جدول دلخواه (مشترک بین برنامه هفتگی چندپایه و تک‌پایه) =====
  function lbXNewId(){return 'c'+Date.now().toString(36)+Math.floor(Math.random()*46656).toString(36);}
  function lbXNorm(x){
    x=(x&&typeof x==='object')?x:{};
    if(!Array.isArray(x.cols))x.cols=[];
    if(!Array.isArray(x.tables))x.tables=[];
    x.tables.forEach(function(t){
      if(!t.id)t.id=lbXNewId();
      if(t.title==null)t.title='';
      if(!Array.isArray(t.headers)||!t.headers.length)t.headers=['ستون ۱','ستون ۲','ستون ۳'];
      if(!Array.isArray(t.rows))t.rows=[];
      t.rows=t.rows.map(function(r){r=Array.isArray(r)?r:[];while(r.length<t.headers.length)r.push('');return r;});
    });
    return x;
  }
  function lbXColNames(x){return x.cols.map(function(c){return c.name;});}
  function lbXHeadCells(x,forExport){
    var h='';
    x.cols.forEach(function(c){
      h+='<th>'+esc(c.name)+(forExport?'':' <span class="lb-x-tools"><button type="button" class="lb-x-btn" data-xact="col-ren" data-id="'+c.id+'" title="تغییر نام ستون">✏️</button><button type="button" class="lb-x-btn" data-xact="col-del" data-id="'+c.id+'" title="حذف ستون">✖</button></span>')+'</th>';
    });
    return h;
  }
  function lbXCellsHtml(x,dataObj,prefix,forExport,rowHex,cls){
    var h='';
    x.cols.forEach(function(c){
      var key=prefix+'x'+c.id;
      var v=dataObj[key]||'';
      h+=forExport?'<td style="background:'+(rowHex||'#fff')+'">'+esc(v).replace(/\\n/g,'<br>')+'</td>':'<td><textarea class="'+cls+'" rows="1" data-key="'+key+'">'+esc(v)+'</textarea></td>';
    });
    return h;
  }
  function lbXTablesHtml(x,forExport){
    var h='';
    x.tables.forEach(function(t){
      h+='<div class="lb-xtable-wrap" style="margin-top:18px">';
      if(forExport){
        if(t.title)h+='<p style="font-weight:700;margin:6px 0">'+esc(t.title)+'</p>';
      }else{
        h+='<div class="lb-xt-head"><span class="lb-xt-title" contenteditable="true" data-tid="'+t.id+'" data-ph="عنوان جدول">'+esc(t.title)+'</span>'
          +'<button type="button" class="btn sm sec" data-xact="xt-addrow" data-tid="'+t.id+'">➕ ردیف</button>'
          +'<button type="button" class="btn sm sec" data-xact="xt-addcol" data-tid="'+t.id+'">➕ ستون</button>'
          +'<button type="button" class="btn sm danger" data-xact="xt-del" data-tid="'+t.id+'">🗑️ حذف جدول</button></div>';
      }
      h+='<table class="lb-table lb-table-tight" style="width:100%"><thead><tr>';
      t.headers.forEach(function(hd,ci){
        h+='<th>'+(forExport?esc(hd):'<span class="lb-xt-h" contenteditable="true" data-tid="'+t.id+'" data-c="'+ci+'">'+esc(hd)+'</span> <button type="button" class="lb-x-btn" data-xact="xt-delcol" data-tid="'+t.id+'" data-c="'+ci+'" title="حذف ستون">✖</button>')+'</th>';
      });
      if(!forExport)h+='<th style="min-width:20px"></th>';
      h+='</tr></thead><tbody>';
      t.rows.forEach(function(r,ri){
        h+='<tr>';
        t.headers.forEach(function(hd,ci){
          var v=r[ci]||'';
          h+=forExport?'<td>'+esc(v).replace(/\\n/g,'<br>')+'</td>':'<td><textarea class="lb-xt-cell" rows="1" data-tid="'+t.id+'" data-r="'+ri+'" data-c="'+ci+'">'+esc(v)+'</textarea></td>';
        });
        if(!forExport)h+='<td><button type="button" class="lb-x-btn" data-xact="xt-delrow" data-tid="'+t.id+'" data-r="'+ri+'" title="حذف ردیف">✖</button></td>';
        h+='</tr>';
      });
      h+='</tbody></table></div>';
    });
    return h;
  }
  function lbXAddCol(x,rerender){
    var nm=prompt('نام ستون جدید (بعد از زنگ پنجم اضافه می‌شود):','');
    if(nm===null)return;
    nm=nm.trim();
    if(!nm){toast('نام ستون را وارد کنید');return;}
    x.cols.push({id:lbXNewId(),name:nm});
    rerender();
  }
  function lbXAddTable(x,rerender){
    var title=prompt('عنوان جدول جدید (اختیاری):','');
    if(title===null)return;
    var t={id:lbXNewId(),title:title.trim(),headers:['ستون ۱','ستون ۲','ستون ۳'],rows:[['','',''],['','',''],['','','']]};
    x.tables.push(t);
    rerender();
  }
  function lbXAddExcelSheets(wb,x){
    x.tables.forEach(function(t,i){
      var rows=[t.headers.slice()].concat(t.rows.map(function(r){return t.headers.map(function(hd,ci){return r[ci]||'';});}));
      var nm='جدول '+(i+1)+(t.title?' - '+t.title:'');
      ['/','?','*','[',']',':',String.fromCharCode(92)].forEach(function(ch){nm=nm.split(ch).join(' ');});
      lbAddExcelSheet(wb,nm,rows);
    });
  }
  function lbXWire(el,getX,getData,rerender){
    function findT(id){return getX().tables.filter(function(k){return k.id===id;})[0];}
    el.addEventListener('click',function(e){
      var b=e.target.closest('[data-xact]');
      if(!b||!el.contains(b))return;
      var x=getX(),act=b.dataset.xact,t=null,i;
      if(b.dataset.tid){t=findT(b.dataset.tid);if(!t)return;}
      if(act==='col-del'||act==='col-ren'){
        var col=x.cols.filter(function(k){return k.id===b.dataset.id;})[0];
        if(!col)return;
        if(act==='col-ren'){
          var nn=prompt('نام جدید ستون:',col.name);
          if(nn===null)return;
          nn=nn.trim();
          if(!nn)return;
          col.name=nn;
        }else{
          if(!confirm('ستون «'+col.name+'» حذف شود؟ اطلاعات داخل این ستون هم پاک می‌شود.'))return;
          x.cols=x.cols.filter(function(k){return k.id!==col.id;});
          var d=getData();
          Object.keys(d).forEach(function(k){if(k.slice(-(col.id.length+1))==='x'+col.id)delete d[k];});
        }
        rerender();
      }else if(act==='xt-del'){
        if(!confirm('این جدول با همه‌ی اطلاعاتش حذف شود؟'))return;
        x.tables=x.tables.filter(function(k){return k.id!==t.id;});
        rerender();
      }else if(act==='xt-addrow'){
        t.rows.push(t.headers.map(function(){return '';}));
        rerender();
      }else if(act==='xt-addcol'){
        t.headers.push('ستون '+toFaDigits(t.headers.length+1));
        t.rows.forEach(function(r){r.push('');});
        rerender();
      }else if(act==='xt-delcol'){
        if(t.headers.length<=1){toast('حداقل یک ستون باید بماند');return;}
        i=parseInt(b.dataset.c,10);
        if(!confirm('این ستون حذف شود؟'))return;
        t.headers.splice(i,1);
        t.rows.forEach(function(r){r.splice(i,1);});
        rerender();
      }else if(act==='xt-delrow'){
        i=parseInt(b.dataset.r,10);
        t.rows.splice(i,1);
        rerender();
      }
    });
    el.addEventListener('input',function(e){
      var tg=e.target;
      if(!tg||!tg.classList)return;
      var t=tg.dataset&&tg.dataset.tid?findT(tg.dataset.tid):null;
      if(!t)return;
      if(tg.classList.contains('lb-xt-cell')){
        var r=parseInt(tg.dataset.r,10),c=parseInt(tg.dataset.c,10);
        if(t.rows[r])t.rows[r][c]=tg.value;
        lbAutoResizeStaffTa(tg);
      }else if(tg.classList.contains('lb-xt-title')){
        t.title=tg.textContent;
      }else if(tg.classList.contains('lb-xt-h')){
        t.headers[parseInt(tg.dataset.c,10)]=tg.textContent;
      }
    });
  }

  // ===== فونت، اندازه و تم مشترک جدول‌های برنامه‌ی هفتگی (چندپایه و تک‌پایه) =====
  var WK_LEGACY_FONT={'bnazanin':'B Nazanin','bmitra':'B Mitra','nazanin':'B Nazanin','titr':'B Titr','mitra':'B Mitra'};
  function wkEl(p,k){return document.getElementById(p+'-'+k);}
  function wkSize(p){var s=parseInt(wkEl(p,'font-size').value,10)||14;return Math.max(8,Math.min(40,s));}
  function wkFont(p){var v=wkEl(p,'font').value;return RCC.fontName(WK_LEGACY_FONT[v]||v);}
  function wkHead(p){var v=wkEl(p,'head-font').value;return RCC.fontName(WK_LEGACY_FONT[v]||v);}
  function wkTheme(p){return RCC.theme(wkEl(p,'theme').value);}
  function wkFamily(p){return RCC.fontCss(wkFont(p));}
  function wkApplyVars(p,panelId){
    var el=document.getElementById(panelId);
    if(!el)return;
    var T=wkTheme(p);
    el.style.setProperty('--wk-font',RCC.fontCss(wkFont(p)));
    el.style.setProperty('--wk-head-font',RCC.fontCss(wkHead(p)));
    el.style.setProperty('--wk-size',wkSize(p)+'px');
    el.style.setProperty('--wk-a',T.a);el.style.setProperty('--wk-ink',T.ink);el.style.setProperty('--wk-line',T.line);
    el.style.setProperty('--wk-tint',T.tint);el.style.setProperty('--wk-b1',T.band[0]);el.style.setProperty('--wk-b2',T.band[1]);
  }
  function wkInit(p,panelId,styleKey,onApply){
    var opts=PC_FONT_LIST.map(function(f){return '<option value="'+f[0]+'" style="font-family:'+PC_Q+f[0]+PC_Q+',Tahoma">'+f[1]+'</option>';}).join('');
    wkEl(p,'font').innerHTML=opts;wkEl(p,'head-font').innerHTML=opts;
    wkEl(p,'font').value='B Nazanin';wkEl(p,'head-font').value='B Nazanin';
    wkEl(p,'theme').innerHTML=RCC.THEMES.map(function(t){return '<option value="'+t.id+'">'+t.name+'</option>';}).join('');
    function changed(){
      wkApplyVars(p,panelId);
      if(onApply)onApply();
      lbSave(styleKey,{font:wkFont(p),head:wkHead(p),theme:wkTheme(p).id,size:wkSize(p)},true);
    }
    ['font','head-font','theme'].forEach(function(k){wkEl(p,k).addEventListener('change',changed);});
    wkEl(p,'font-size').addEventListener('input',changed);
    document.getElementById('btn-'+p+'-fontsize-inc').onclick=function(){wkEl(p,'font-size').value=Math.min(40,wkSize(p)+1);changed();};
    document.getElementById('btn-'+p+'-fontsize-dec').onclick=function(){wkEl(p,'font-size').value=Math.max(8,wkSize(p)-1);changed();};
  }
  function wkApplyLoaded(p,st){
    if(!st)return;
    var f=st.font?RCC.fontName(WK_LEGACY_FONT[st.font]||st.font):null;
    if(f)wkEl(p,'font').value=f;
    var h=st.head?RCC.fontName(st.head):null;
    if(h)wkEl(p,'head-font').value=h;else if(f)wkEl(p,'head-font').value=f;
    if(st.theme)wkEl(p,'theme').value=RCC.theme(st.theme).id;
    if(st.size)wkEl(p,'font-size').value=st.size;
  }
  var WK_DAY_BG=[0,1,2,3,4].map(function(i){return LB_GROUP_COLORS[i];});
  // اجزای مشترک خروجی Word / چاپ
  function wkTitle(title,T,fh){
    return '<div style="height:7px;background:'+T.band[0]+';background:linear-gradient(90deg,'+T.band[0]+','+T.band[1]+');border-radius:6px;margin-bottom:10px;font-size:1px;line-height:1px">&nbsp;</div>'
      +'<p style="text-align:center;font-weight:bold;font-size:1.5em;margin:0 0 4px;color:'+T.ink+';font-family:'+fh+'">'+esc(title)+'</p>'
      +'<div style="width:110px;margin:0 auto 12px;border-bottom:4px solid '+T.band[0]+';height:2px;font-size:1px;line-height:1px">&nbsp;</div>';
  }
  function wkInfo(pairs,T,fh){
    var n=pairs.length,w=(100/n/2).toFixed(2);
    var lab='border:1px solid '+T.line+';padding:7px 8px;background:'+T.a+';color:'+T.ink+';font-weight:bold;text-align:center;font-family:'+fh+';';
    var val='border:1px solid '+T.line+';padding:7px 8px;text-align:right;';
    var h='<table style="width:100%;border-collapse:collapse;table-layout:fixed;margin-bottom:12px"><colgroup>'+pairs.map(function(){return '<col style="width:'+(w*0.7).toFixed(2)+'%"><col style="width:'+(w*1.3).toFixed(2)+'%">';}).join('')+'</colgroup><tr>';
    pairs.forEach(function(pr){
      var s=pr[1]&&String(pr[1]).trim()?esc(pr[1]):'&nbsp;';
      h+='<td style="'+lab+'">'+esc(pr[0])+'</td><td style="'+val+'">'+s+'</td>';
    });
    return h+'</tr></table>';
  }
  function wkNl(s){return esc(s||'').split(String.fromCharCode(13)).join('').split(String.fromCharCode(10)).join('<br>');}
  function wkCustomTables(x,T,fh){
    var h='';
    x.tables.forEach(function(t){
      var cell='border:1px solid '+T.line+';padding:7px 6px;vertical-align:middle;text-align:center;line-height:1.7;';
      if(t.title)h+='<p style="font-weight:bold;margin:16px 0 6px;color:'+T.ink+';font-family:'+fh+'">'+esc(t.title)+'</p>';
      else h+='<div style="height:12px">&nbsp;</div>';
      h+='<table style="width:100%;border-collapse:collapse;table-layout:fixed;border:1px solid '+T.line+'"><thead><tr>';
      t.headers.forEach(function(hd){h+='<th style="'+cell+'background:'+T.a+';color:'+T.ink+';font-weight:bold;font-family:'+fh+'">'+esc(hd)+'</th>';});
      h+='</tr></thead><tbody>';
      t.rows.forEach(function(r,ri){
        h+='<tr style="page-break-inside:avoid">';
        t.headers.forEach(function(hd,ci){
          var v=r[ci]||'';
          h+='<td style="'+cell+(ri%2===1?'background:'+T.tint+';':'')+'">'+(v?wkNl(v):'&nbsp;')+'</td>';
        });
        h+='</tr>';
      });
      h+='</tbody></table>';
    });
    return h;
  }
  function wkWord(p,title,html,filename,landscape){
    lbWordExport('',html,filename,landscape,wkFamily(p),Math.max(8,wkSize(p)-2));
  }
  function wkPrint(p,title,html,landscape){
    var w=window.open('','_blank');
    if(!w){toast('اجازه‌ی باز کردن پنجره‌ی چاپ داده نشد (popup blocked)');return;}
    var css='<style>'+RCC.faceCss(location.origin)+'@page{size:A4 '+(landscape?'landscape':'portrait')+';margin:8mm}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}'
      +'body{direction:rtl;margin:0;padding:4px;font-family:'+wkFamily(p)+';font-size:'+Math.max(8,wkSize(p)-2)+'px;color:#1f2937}table,td,th{font-size:inherit;word-break:break-word}thead{display:table-header-group}tr{page-break-inside:avoid}</style>';
    w.document.write('<!DOCTYPE html><html dir="rtl"><head><meta charset="utf-8"><title>'+esc(title)+'</title>'+css+'</head><body>'+html+'</body></html>');
    w.document.close();
    printExportWindow(w);
  }

  // ===================== ۷. برنامه درسی هفتگی (ویژه چندپایه) - جدول ۱-۳-۱ =====================
  var LB_WEEKLY_DAYS=['شنبه','یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه'];
  var LB_WEEKLY_GRADE_NAMES=['اول','دوم','سوم','چهارم','پنجم','ششم'];
  var LB_WEEKLY_X={cols:[],tables:[]}; // ستون‌ها و جدول‌های دلخواه
  var LB_WEEKLY_DATA={}; // key: 'dayIdx-gradeIdx-sessionIdx' -> مقدار سلول (gradeIdx همیشه بر اساس شماره‌ی واقعی پایه ۰ تا ۵ است، حتی اگر آن پایه فعلاً انتخاب نشده باشد)
  function lbSelectedWeeklyGrades(){
    var out=[];
    document.querySelectorAll('.lbw-grade-chk').forEach(function(chk,idx){
      if(chk.checked)out.push(idx);
    });
    return out;
  }
  function lbBuildWeeklyHtml(forExport){
    if(forExport)return lbWeeklyExportTable();
    var grades=lbSelectedWeeklyGrades();
    if(!grades.length)grades=[0,1,2,3,4,5];
    var h='<p class="lbw-cap">📅 برنامه درسی چندپایه</p>';
    h+='<table class="lb-table lb-table-tight" style="width:100%"><thead><tr><th>روز</th><th>پایه</th><th>زنگ اول</th><th>زنگ دوم</th><th>زنگ سوم</th><th>زنگ چهارم</th><th>زنگ پنجم</th>'+lbXHeadCells(LB_WEEKLY_X,false)+'</tr></thead><tbody>';
    LB_WEEKLY_DAYS.forEach(function(day,dIdx){
      var dc=LB_GROUP_COLORS[dIdx%LB_GROUP_COLORS.length];
      grades.forEach(function(gIdx,i){
        var rowKey='row-'+dIdx+'-'+gIdx;
        var gc=LB_GROUP_COLORS[gIdx%LB_GROUP_COLORS.length];
        h+='<tr>';
        if(i===0)h+='<td class="lbw-day" rowspan="'+grades.length+'" style="background:'+dc.head+';color:'+dc.ink+'">'+esc(day)+'</td>';
        h+='<td class="lbw-grade" style="background:'+gc.head+';color:'+gc.ink+'">'+LB_WEEKLY_GRADE_NAMES[gIdx]+rowColorDotsHtml(rowKey)+'</td>';
        for(var s=0;s<5;s++){
          var key=dIdx+'-'+gIdx+'-'+s;
          var v=LB_WEEKLY_DATA[key]||'';
          h+='<td><textarea class="lb-weekly-cell" rows="1" data-key="'+key+'">'+esc(v)+'</textarea></td>';
        }
        h+=lbXCellsHtml(LB_WEEKLY_X,LB_WEEKLY_DATA,dIdx+'-'+gIdx+'-',false,'','lb-weekly-cell');
        h+='</tr>';
      });
    });
    h+='</tbody></table>';
    h+=lbXTablesHtml(LB_WEEKLY_X,false);
    return h;
  }
  // جدول خروجی Word/چاپ: ستون‌های هم‌اندازه، سرتیتر تکرارشونده، روزها و پایه‌ها با رنگ ملایم
  function lbWeeklyExportTable(){
    var T=wkTheme('lbw'),fh=RCC.fontCss(wkHead('lbw'));
    var grades=lbSelectedWeeklyGrades();
    if(!grades.length)grades=[0,1,2,3,4,5];
    var X=LB_WEEKLY_X,nx=X.cols.length;
    var wDay=9,wGrade=8,each=((100-wDay-wGrade)/(5+nx)).toFixed(3);
    var cell='border:1px solid '+T.line+';padding:8px 5px;vertical-align:middle;text-align:center;line-height:1.7;font-weight:bold;';
    var h='<table style="width:100%;border-collapse:collapse;table-layout:fixed;border:1px solid '+T.line+'"><colgroup><col style="width:'+wDay+'%"><col style="width:'+wGrade+'%">';
    for(var i=0;i<5+nx;i++)h+='<col style="width:'+each+'%">';
    h+='</colgroup><thead style="display:table-header-group"><tr>';
    ['روز','پایه','زنگ اول','زنگ دوم','زنگ سوم','زنگ چهارم','زنگ پنجم'].concat(lbXColNames(X)).forEach(function(t){
      h+='<th style="'+cell+'background:'+T.a+';color:'+T.ink+';font-family:'+fh+'">'+esc(t)+'</th>';
    });
    h+='</tr></thead><tbody>';
    LB_WEEKLY_DAYS.forEach(function(day,dIdx){
      var dc=LB_GROUP_COLORS[dIdx%LB_GROUP_COLORS.length];
      grades.forEach(function(gIdx,i){
        var rowHex=ROW_COLOR_HEX[lbWeeklyRowColors['row-'+dIdx+'-'+gIdx]]||'';
        var gc=LB_GROUP_COLORS[gIdx%LB_GROUP_COLORS.length];
        var top=i===0?'border-top:2px solid '+T.line+';':'';
        var bg=rowHex?'background:'+rowHex+';':'';
        h+='<tr style="page-break-inside:avoid">';
        if(i===0)h+='<td rowspan="'+grades.length+'" style="'+cell+'background:'+dc.head+';color:'+dc.ink+';font-family:'+fh+';font-size:1.1em">'+esc(day)+'</td>';
        h+='<td style="'+cell+top+'background:'+(rowHex||gc.head)+';color:'+gc.ink+';font-family:'+fh+'">'+LB_WEEKLY_GRADE_NAMES[gIdx]+'</td>';
        for(var s=0;s<5;s++){
          var v=LB_WEEKLY_DATA[dIdx+'-'+gIdx+'-'+s]||'';
          h+='<td style="'+cell+top+bg+'">'+(v?wkNl(v):'&nbsp;')+'</td>';
        }
        X.cols.forEach(function(c){
          var xv=LB_WEEKLY_DATA[dIdx+'-'+gIdx+'-x'+c.id]||'';
          h+='<td style="'+cell+top+bg+'">'+(xv?wkNl(xv):'&nbsp;')+'</td>';
        });
        h+='</tr>';
      });
    });
    return h+'</tbody></table>';
  }
