  // ===================== ۸. برنامه درسی هفتگی (کلاس تک‌پایه) - جدول ۳ =====================
  var LB_WEEKLY2_DAYS=['شنبه','یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه'];
  var LB_WEEKLY2_SESSIONS=['زنگ اول','زنگ دوم','سوم','چهارم','پنجم'];
  var LB_WEEKLY2_X={cols:[],tables:[]}; // ستون‌ها و جدول‌های دلخواه
  var LB_WEEKLY2_DATA={}; // key: 'dayIdx-sessionIdx'
  function lbWeekly2DiagCellHtml(forExport){
    if(forExport){
      // استایل inline کامل تا در فایل Word/چاپ هم (بدون وابستگی به استایل صفحه) درست دیده شود
      return '<th style="position:relative;padding:0;height:44px;min-width:70px;'
        +'background:linear-gradient(to top left, transparent calc(50% - 1px), #94a3b8 calc(50% - 1px), #94a3b8 calc(50% + 1px), transparent calc(50% + 1px))">'
        +'<span style="position:absolute;top:2px;left:6px;font-size:10px;font-weight:700">زنگ</span>'
        +'<span style="position:absolute;bottom:2px;right:6px;font-size:10px;font-weight:700">روز</span>'
        +'</th>';
    }
    return '<th class="lb-diag-cell"><span class="lb-diag-top">زنگ</span><span class="lb-diag-bottom">روز</span></th>';
  }
  function lbBuildWeekly2Html(forExport){
    if(forExport)return lbWeekly2ExportTable();
    var h='<table class="lb-table lb-table-tight" style="width:100%"><thead><tr>';
    h+=lbWeekly2DiagCellHtml(false);
    LB_WEEKLY2_SESSIONS.forEach(function(s){h+='<th>'+esc(s)+'</th>';});
    h+=lbXHeadCells(LB_WEEKLY2_X,false);
    h+='</tr></thead><tbody>';
    LB_WEEKLY2_DAYS.forEach(function(day,dIdx){
      var rowKey='day-'+dIdx;
      var dc=LB_GROUP_COLORS[dIdx%LB_GROUP_COLORS.length];
      h+='<tr><td class="lbw-day" style="background:'+dc.head+';color:'+dc.ink+'">'+esc(day)+rowColorDotsHtml(rowKey)+'</td>';
      LB_WEEKLY2_SESSIONS.forEach(function(s,sIdx){
        var key=dIdx+'-'+sIdx;
        var v=LB_WEEKLY2_DATA[key]||'';
        h+='<td><textarea class="lb-weekly2-cell" rows="1" data-key="'+key+'">'+esc(v)+'</textarea></td>';
      });
      h+=lbXCellsHtml(LB_WEEKLY2_X,LB_WEEKLY2_DATA,dIdx+'-',false,'','lb-weekly2-cell');
      h+='</tr>';
    });
    h+='</tbody></table>';
    h+=lbXTablesHtml(LB_WEEKLY2_X,false);
    return h;
  }
  function lbWeekly2ExportTable(){
    var T=wkTheme('lbw2'),fh=RCC.fontCss(wkHead('lbw2'));
    var X=LB_WEEKLY2_X,nx=X.cols.length,wDay=12,each=((100-wDay)/(5+nx)).toFixed(3);
    var cell='border:1px solid '+T.line+';padding:16px 6px;vertical-align:middle;text-align:center;line-height:1.7;font-weight:bold;';
    var hcell='border:1px solid '+T.line+';padding:9px 6px;vertical-align:middle;text-align:center;font-weight:bold;background:'+T.a+';color:'+T.ink+';font-family:'+fh+';';
    var h='<table style="width:100%;border-collapse:collapse;table-layout:fixed;border:1px solid '+T.line+'"><colgroup><col style="width:'+wDay+'%">';
    for(var i=0;i<5+nx;i++)h+='<col style="width:'+each+'%">';
    h+='</colgroup><thead style="display:table-header-group"><tr><th style="'+hcell+'">روز / زنگ</th>';
    LB_WEEKLY2_SESSIONS.concat(lbXColNames(X)).forEach(function(t){h+='<th style="'+hcell+'">'+esc(t)+'</th>';});
    h+='</tr></thead><tbody>';
    LB_WEEKLY2_DAYS.forEach(function(day,dIdx){
      var rowHex=ROW_COLOR_HEX[lbWeekly2RowColors['day-'+dIdx]]||'';
      var dc=LB_GROUP_COLORS[dIdx%LB_GROUP_COLORS.length];
      var bg=rowHex?'background:'+rowHex+';':'';
      h+='<tr style="page-break-inside:avoid"><td style="'+cell+'background:'+(rowHex||dc.head)+';color:'+dc.ink+';font-family:'+fh+';font-size:1.1em">'+esc(day)+'</td>';
      LB_WEEKLY2_SESSIONS.forEach(function(s,sIdx){
        var v=LB_WEEKLY2_DATA[dIdx+'-'+sIdx]||'';
        h+='<td style="'+cell+bg+'">'+(v?wkNl(v):'&nbsp;')+'</td>';
      });
      X.cols.forEach(function(c){
        var xv=LB_WEEKLY2_DATA[dIdx+'-x'+c.id]||'';
        h+='<td style="'+cell+bg+'">'+(xv?wkNl(xv):'&nbsp;')+'</td>';
      });
      h+='</tr>';
    });
    return h+'</tbody></table>';
  }
